window.POEM_DB=window.POEM_DB||{};POEM_DB["qing_019"]={"n":"李锴","dyn":"清","poems":[{"t":"云冈寺","f":"七言律诗","c":["黄金易销木易朽，即山作佛佛乃寿。","五丁风斤齐琢剖，一峰破碎万象有。","四十七尺身独尊，三万六千日何久。","崔浩已死可若何，后之君子扬其波。"]},{"t":"山海关","f":"七言律诗","c":["关路无人雪自消，兴亡千载一昏朝。","岛门失势鱼龙震，亭障乘秋虎豹骄。","白草已堙先轸血，青天谁奋伍员潮。","可怜万里绵秦塞，不救咸阳赤土焦。"]},{"t":"凤皇山","f":"七言绝句","c":["凤皇山上叠琼台，丝管年年曲宴开。","五国城头霜夜角，朔风辛苦莫吹来。"]},{"t":"登北极台","f":"七言律诗","c":["含睇高城接渺茫，饥乌飞噪古台荒。","沙连秋水寒皋迥，山拥晴云落日黄。","边塞关心双宝剑，亲朋满目一空囊。","廿年不偶伶俜影，宾戏真难答省郎。"]},{"t":"鲤石行","f":"古风","c":["吾闻东海之鲤能变化，湖山飞越唯须臾。","此石形状苦神似，往者毋乃真巨鱼。","怒目轮囷大于斗，鼓鬐振鬣势欲走。","倚峡犹飞失水心，冲天直奋吞舟口。","惨澹风云入憔悴，土花石藓空鳞次。","江湖何日得相忘，蝼蚁能无受其制。","阴潭秋雨沈沈急，龙母叫啸鲛人泣。","君不见朽瓜乌足何太神，解化江鱼与胡蝶。"]},{"t":"赠李雄李库兄弟","f":"七言古诗","c":["束发承恩领边务，长剑划破阴山雾。","从行李氏四十人，兄弟今存雄与库。","曳杖相逢村树边，把手殷勤问新故。","君年十八今五十，人生信如草头露。","边霜如刀割人面，犹记当时逞雄健。","异身同命走殊域，手指堕落心无閒。","即今垂死骨髓枯，一中秋风肌肉颤。","语罢淫淫涕如霰，不死他时再相见。","感之赠以钱一串，亦知贱子长贫贱。"]},{"t":"坐仙人桥望西峰红树","f":"七言古诗","c":["白云之半西峰西，秋树十万红锦披。","紫金交注宝丝网，碧海晴拥珊瑚枝。","西风泠泠时中之，云璈宛转清商移。","采旄飏云巫女下，豹旗揭雨山鬼啼。","枝枝叶叶迎薄寒，山僧野客争来看。","关河岁晚金气肃，青帝假尔丹砂颜。","外方作态中则病，色若可怜心不竞。","山烟欲暝严霜飞，松柏萧萧有本性。"]},{"t":"雪后踏雪听倒影潭水","f":"七言古诗","c":["野鸡乱印前溪步，槎牙玉削沙头树。","芒鞋踏雪雪不污，捷辟西南人潭路。","群动蛰伏万籁喑，飞空激响潭流深。","黄钟大吕方并扣，金奏地下惊欲走。","我有深情久相对，青藤杖击层冰碎。","乌黔鹄白天不移，湛然独立空明外。"]},{"t":"题李卫公待渡图","f":"古风","c":["太原公子方隶军，药师却渡黄河津。","津头萧萧风雪暮，亦是寻常行路人。","惊龙怒虎易形似，难画英雄当此际。","常山太华隐欲动，千尺光芒垂至地。","短衣长剑奇仿佛，妙处胸中如有物。","赤云敢击天子气，黄金待铸通侯骨。","呜呼丈夫古来抱奇诡，宛转几人岩下死！","射钩倘恶晋公子，骅骝又死盐车底。"]},{"t":"古藤歌","f":"七言古诗","c":["葛甥东园余古藤，十年委弃栖陂艿。","支离不死亦不生，根蟠元气犹支撑。","枯条高折兕角秃，朽腹半裂鱼膏青。","有时一花两花发，流苏倒挂红丝绳。","沈精阴脉自得主，枯菀不假春风能。","一朝移根忽我寄，伧父邪许牛车胜。","白茅用藉索以约，龙胡或见髯鬅鬙。","云中飙举帝子下，丘园帛贲徵君行。","城南沃土买百篑，活水远汲长河清。","封殖灌溉不遗力，高杉复架藤花棚。","酹君杯酒慎莫死，老夫与若聊相凭。"]},{"t":"新竹歌","f":"七言古诗","c":["少年日作江南游，大竹小竹青满眼。","菅茅土苴不足惜，樵父编篱渔作断。","蓟丘在昔植汶篁，不信于今此物罕。","丰台土膏颇润湿，人夺天工尚强勉。","西施在越了不觉，异人寄赵珍无算。","青钱一百栽一本，琅玕琬琰矜殊产。","王猷宿好老不已，购之不惜衣裳典。","鹿车辚辚为我辇，老竹如麻雉子短。","晨昏芟剔手自护，已疗山翁十年懒。","三月春风泠然善，江烟水色纷萧散，忽然移我三湘远。"]},{"t":"焚诗歌为石东村作","f":"古风","c":["古诗旧说三千篇，未必皆是宣尼删。","河清菅蒯颇可诵，春秋交聘犹能宣。","逸而不逸谁则主，少者为贵翻争传。","石君一旦过我门，道腴义胜来骄人。","生平为诗不知数，告我草稿今通焚。","丈夫猛捷贵有断，龙蜕不惜黄金鳞。","君看《笙诗》无一字，束氏补之成赘文。","我闻此论骇卓绝，至人之迹神其灭。","白贲无咎世莫讦，脱身天外穷毫末。","吁嗟乎，君休矣！","宝华玉气恐不死，或有人间传片纸。"]},{"t":"闻归雁感赋","f":"五言律诗","c":["毕竟家何处，而云北是归。","高城残照下，万里一行飞。","风急毋相乱，沙寒定有依。","畸人方失序，缘汝泪沾衣。"]},{"t":"寄赠戴通乾 其一","f":"五言律诗","c":["委巷精庐小，过从正苦寒。","诗吟百遍过，酒借一杯宽。","激楚朱弦瑟，凄凉白玉盘。","故交京洛满，妻子恕艰难。"]},{"t":"寄赠戴通乾 其二","f":"五言律诗","c":["三老辽东旧，而今各暮途。","寒风自萧索，幽草不荒芜。","冰雪春心长，风尘此态无。","市中逢皂帽，曾识管宁无。"]},{"t":"寄答戴通乾","f":"七言律诗","c":["故人哆口说仪型，歧路萧条见客星。","独立望乡聊自遣，一酣倚酒未全醒。","越中踪迹潜张廌，海上文章著管宁。","莫问盘阴老樵父，断云枯木共沈冥。"]},{"t":"朱鹭","f":"古风","c":["鹭飞来，何常羊。","鹭将栖，倡六茎。","尊则有象彝有黄。","器充厥实表乃章。","鼓之咽咽，若存若亡。"]},{"t":"艾如张","f":"古风","c":["艾如张，张于田之下。","左杀得鴽，右杀得鼠。","前蹊芃芃立猛虎。","劝君莫走马，走马马折跨。"]},{"t":"巫山高","f":"古风","c":["巫山长，淮水深。","我有远心，末由以南。","巫山高，淮水浅。","沙口舟长棹尾短。","我欲褰裳涉之，疾不治缓。","会稽无人，靡视睍睍。","长镵归来，刬巫山断。"]},{"t":"将进酒","f":"楚辞体","c":["将进酒，夜将半。","饥乌雅雅承曷旦。","梁郑女儿正操缦。","注耳回心入澶漫。","醉起更衣衣历乱。","匪手孰携，匪口孰吹。","金罍之舟，不可以自移。","于嗟兮奈何。"]},{"t":"临高台","f":"古风","c":["春日临高台，高台淩四荒。","与客周顾之，蜿蜿双飞龙。","关弓射龙脊，下中鲤与鲂。","长跪烹鲤鱼，牛羊夺臐膷。","贡君千秋万岁乐，愿君乐未央。"]},{"t":"有所思","f":"古风","c":["食有炮牂，不如黄粱。","邦有齐梁，不如故乡。","浮舟九河徒怀望，但见落日曛以黄。","磨我金错刀，削我青竹简，片语投人人莫辨。","鸳鸯失水鱼负巘，昔有所思今则殄。"]},{"t":"君马黄","f":"古风","c":["君马黄，臣马黄。","两骖随靳相回翔，纆牵冲冲从短长。","君马黄，臣马白。","赠君黄棘之枉策，可以南，可以北。"]},{"t":"芳树","f":"古风","c":["芳树汝藉汝阴，芳树汝独何心。","我有步光剑，切玉不切泥。","我有昆吾刀，杀牛不杀鸡。","我于汝，奈之何哉，双睫淫淫涕交注。","腹转车轮自归去，旦晚寒阴湿生蠹。"]},{"t":"雉子斑","f":"古风","c":["雉子斑，河之梁。","童得雉子用以烹，翁得雉子用以羹。","母乃引，子口且黄，母饮水，子啄粻。","群飞飞从公子。","公子去来，得车已多。","公子归来，得车已多。"]},{"t":"圣人出","f":"古风","c":["圣人出，绥绥而。","圣人出，䙾䙾而。","嫛弥黎老无殿屎。","期门羽林，带刀跨马，皆能闲礼仪。","醇德洽，物无暌。","携河鱼，呴以沫，雉宿我栭。","圣人出，出以时。"]},{"t":"钓鱼篇","f":"古风","c":["鱼之洋洋，避我钓竿。","鱼则无求，维钓有干。","飞尘疾流，实行路难。","影乱于目，迹乱于足。","谓是寐言，杲杲日瞩。","悠悠寸心，系我河曲。","云乎归休，谁我此复。"]},{"t":"长歌行","f":"五言古诗","c":["朝出上东门，走马平原间。","箭截姈胡笴，弓张麻林弦。","射鸟亦射狼，一发矜双联。","妙技跨燕赵，谁能为之先。","生年且七十，累积青铜钱。","积钱欲何为，日买东皋田。","岂知流光催，年寿不长假。","骷髅化狐冠，夜拜青林下。"]},{"t":"薤露","f":"五言古诗","c":["草长不离根，枯杨且生稊。","人生百年间，一去无还期。","原上累累冢，其下瘗者谁。","昨日乡里中，白马耀金羁。","一语不得意，按剑成恣睢。","精魄既失我，骨肉如涂泥。","亲戚环咨嗟，娇儿捧故衣。","少妇等畴昔，茕茕为鬼妻。"]},{"t":"鸡鸣","f":"古风","c":["鸡长鸣，天苍苍，腷腷膊膊锦翼张。","旦气感召蒙阴阳。","丈人何所为，丈人非寻常。","大男骑都尉，小男典文章。","女婿金爵冠，诸孙罗雁行。","生存谋鼎食，死亦飨膻芗。","瑟瑟春风来，井上桐花黄。","招招唤俦匹，与吾同翱翔。"]},{"t":"乌生八九子","f":"五言古诗","c":["乌生八九子，同生不同死。","野火烧树空，危巢坐成燬。","朝被千金裘，莫著百结衣。","物情自增减，何者为是非。","春菊不有华，冬蚕不结丝。","谁怜青青草，岁晚随风靡。","乌生八九子，同生不同死。"]},{"t":"艳歌罗敷行","f":"五言古诗","c":["张弦弹秦筝，秦筝代人语。","请君侧耳听，听明秦氏女。","秦女自采桑，何与行路人。","使君自行路，何与秦女言。","使君既有言，秦女亦有愿。","我欲从使君，胭脂污人面。","我欲从使君，充耳厌双钿。","我欲从使君，纤手不任钏。","我欲从使君，裙带斜憎襻。","长箭须配弓，金针各随线。","秦女如善从，多时入楚宫。"]},{"t":"董逃行","f":"古风","c":["傅应龙以翼，咄嗟升天。","下视九州，人民薨薨蠕蠕。","薨薨蠕蠕，曾何足与言。","吾谁从乎董逃。","爽鸠不死，齐姜奈何。","黄帝尧舜，乃有阳周与苍梧。","北邙之土，土不异色，安辨夫贤与愚。","吾谁从乎董逃。","世所谓大故，天运冥冥以迁化理。","不拒蹠又安得拒惠。","齿亡舌存，谁则云然，其为后先胡以异。","吾谁从乎董逃。","大火铄金，曾不若百忧销肌。","大火铄金，曾不若百忧销肌。","欲斩艾之，膺有败纰。","膺有败纰，浸淫而化涕洟。","吾谁从乎董逃。","五柞山崔崔，中有云母滑如脂。","旦夕哺之如哺糜。","天门一以开，塞兑阖户资丸泥。","吾谁从乎董逃。"]},{"t":"东门行","f":"古风","c":["长剑不守故乡，班马临歧多悲鸣。","与宛转，向亲故，无宁仆赁于野假以容。","挥手奋将东去，曾无一钱实我囊。","丈夫贫贱死，不若埋殊方。","出东门，唶高柳，啼鹂黄。","行矣慎努力，它日富贵毋相忘。"]},{"t":"野田黄雀行","f":"五言古诗","c":["宿草上大田，岁岁移新陈。","夜风自东来，扇此伤心春。","浍洫岂不具，隧路中横分。","故鬼耿不化，重以新死魂。","百年老狐狸，其间化为人。","气机沮群疑，仡仡徒苦辛。","大鸟不生角，哀哉野田雀。"]},{"t":"气出唱","f":"古风","c":["宁北山，有人上下五色随飞烟。","谢陶正，却不顾，乃含生于火，传体若薪。","我欲从之长死，死则浑沦一气超炎燀。","回视故乡，一何漫漶，骨肉为土精血埏。","顾以离愁沈痛之火，陶我以甄。","鹪鹏闻之大笑，望醯鸡而耸肩。","垂天之云，自东飞来，屏息歆羡，蟪蛄教我以大年。"]},{"t":"猛虎行","f":"五言古诗","c":["走马射猛虎，可杀不可玩。","道旁呻吟人，固知少柔曼。","老父前过之，劝君且强饭。","昔我少年时，短小复精悍。","二十塞瓠子，十五征善鄯。","短刀挥秋风，快马白于练。","生死不后人，论功拙为衒。","白头归故乡，今作侯家佃。","去去毋自苦，还家学格五。"]},{"t":"上留田行","f":"五言古诗","c":["鸿雁不乱序，未必皆同母。","如何连根蓬，枯菀两不同。","寄言爷娘知，慎莫举小儿。","小儿实无罪，有生即为累。","不见上留田，小儿诚可怜。"]},{"t":"饮马长城窟行","f":"五言古诗","c":["阶前促织悲，女儿织素丝。","素丝镇相乱，不绞心愁断。","高楼扃网户，悉索跳梁鼠。","佳期夕已张，明月刚三五。","明月裁入楼，风断珊瑚钩。","大海在东南，众水谁西流。","脉脉复脉脉，求缯误成繴。"]},{"t":"折杨柳行","f":"五言古诗","c":["惠逆凶吉从，匪以人事配。","大道昧于蒙，多令亡故态。","泰伯称至仁，一止嗣谁夺。","回也踵圣轨，厥终丽夭罚。","伋子不逃死，与寿同并命。","伯奇以孝章，厥考非不令。","申徒昔蹈河，三闾亦怀沙。","奢突不旋踵，罹毒理则那。","孔仪交优游，冶死已有馀。","囊瓦秉国程，宛爇已不居。","君一臣则二，大易精义昭。","扶抑每不胜，天道时增忧。"]},{"t":"前缓声歌","f":"古风","c":["琢楮叶以良玉，煽洪垆而造冰。","是不得之于天，欲专之以人固矣哉。","其冬之为冬，夏之为夏，秋之为秋，春之为春。","其有措瓦于危，措户于枢。","与与于于乎，抑又何求已。"]},{"t":"枯鱼过河泣二首 其一","f":"古风","c":["枯鱼过河泣，委骨何拉杂。","坐令老蛟头尾缩，鰦乌齧鳞鳅撼角。","将子无怒聊相谑，须知得此即为乐。"]},{"t":"枯鱼过河泣二首 其二","f":"五言绝句","c":["枯鱼过河泣，鲤鱼飞上天。","附书寄鲤鱼，此去好周旋。"]},{"t":"古咄唶歌","f":"五言古诗","c":["卖肉苦天热，卖浆苦天寒。","不值桑阴人，初不值一钱。","晨鸡倘夕鸣，明日充盘餐。"]},{"t":"豫章行","f":"五言古诗","c":["侵晨上北山，北山行采薪。","蓬蓬豫章木，不惜施斧斤。","百年一日尽，宛转同飙尘。","从君绝我干，慎毋绝我根。","我根蟠黄泉，绝之厚地穿。"]},{"t":"远别离","f":"古风","c":["远别离，谁为之，有情不断如游丝。","君为飘风我为木，枝乃可与君长东西。","白日不上天，海水不入地。","乃使天地间，人生两无事。","攀龙须，拔龙角，乌号在手争逐逐。","我谓黄帝骑龙仙去惨不乐。","君不见桥山姬水两无涉，一身终始何尝合。"]},{"t":"梁父吟","f":"古风","c":["齐云阴，鲁水深。","上客如有意，听我梁父吟。","梁父在何许，乃在泰山下，时有白云如白马。","蔽翳三十六凤皇，雄如乌，雌如鸦，翩然即之喑以哑。","日月大明，雷霆震惊。","纩塞睫合，夺重于轻。","不如假我双羽翼，吾欲御之东过临菑城。","城中管鲍化为土，不见泰山见梁父。"]},{"t":"行行且游猎篇","f":"七言古诗","c":["青丝络头金盘陀，男儿须用好马驮，南山麋鹿苦不多。","左杀右杀随手获，前者丽龟后折骼。","归来买醉长安肆，封侯自是寻常事。","自来马上不读书，偶然识得刀头字。"]},{"t":"飞龙引","f":"古风","c":["形而下者无不死，仙人伐毛且洗髓。","树金盘而射大鱼，天子不得宁其居。","存我丧我两无著，谁能服我长生不死之妙药。","揉木为耒，斲木为耜，弦木为弧，剡木为矢。","飞龙下来谢少年，羲农黄帝寿万千。"]},{"t":"行路难二首 其一","f":"古风","c":["蒲桃美酒留所欢，酒底对面藏波澜。","几人三五寻甘言，为君一歌行路难。","君不见优施尊前好起舞，臧会无言成面阻。","又不见二子戕，三士死，杀人如杀鸡，宛转当前死。","行路难，可若何。","南邻鸡犬自唱叫，老死慎勿相经过。"]},{"t":"行路难二首 其二","f":"古风","c":["吾闻泰山之巅不可以走马，吕梁之壑不可以荡舟。","伯昏下垂二分足，丈人被发且习流。","乃知岩形外张非至险，至险伏在阴之幽。","我将探索之，不可得其繇。","前揖问夫子，劝我长归休。"]},{"t":"长相思","f":"古风","c":["长相思，无已时，昨日今日梦见之。","秋光荧荧夜将半，杂花向人各零乱。","玉漏无声转星汉，黄姑织女遥相盼。","春不得而承春，秋不得而承秋。","如何寸心上，愁罢复添愁。"]},{"t":"前有一樽酒行","f":"古风","c":["君不见首阳祠宇秋草閒，又不见高冢远象祁连山。","古来贤达一二数，尺寸生前竟何补。","十千走买新丰酒，鹦鹉杯深不离手。","了不知南有箕、北有斗，麒麟凤皇鸡犬走，七尺珊瑚如弊帚。","醉起进馀觞，还为乃翁寿。"]},{"t":"独漉篇","f":"楚辞体","c":["独漉泥沙，泥污沙白。","污水洁水，实如过客。","大鱼工食鱼，小鱼唯食泥。","葭菼何苍苍，网罟不得施。","渔人有梦，方舟以行。","风习习兮云冥冥，海若振辔冯夷举旌，丰隆赫怒天吴鸣。","龙母股栗，长鼍轰保，况虾蟆彭蜞及石鲮。","海潮江雨一夕罢，天地万里皆清宁。"]},{"t":"登高丘而望远海","f":"古风","c":["登高丘而望远海，海上浮云白如纸。","不见若木华，但见日小如粟米。","当欲腾身直上乘日车，周流极彼四海之津涯。","天帝下相接，群仙如虫沙。","瀛洲与三山，跬步何污邪。","知不可得还故家，彼往此来良足嗟。","富贵已极可奈何。","可怜汾水上，落日摇空波。"]},{"t":"杨叛儿","f":"古风","c":["乐莫乐，乐平阳，番禺翠羽擎珠珰。","紫罗衫子白霓裳，一夕富贵毋相忘。","男趋女趋，生男弃诸。","今日杨叛儿，昔日卫子夫。"]},{"t":"于阗采花","f":"七言古诗","c":["采花女儿于阗姝，颜色比玉玉不如。","金舆迎之不肯出，千回万转犹自殊。","飞燕合德亲姊妹，闻道同宫还作态。","潇湘之竹一色碧，迄今不染皇英泪。","欲出不出心自怜，春风只在秋风前，与归长信归于阗。"]},{"t":"鞠歌行","f":"古风","c":["骊马曰黄黄马骊，目有真主才知之。","将军门下号多士，独重舍人能好衣。","闻乐欲寐乐必古，苦言中人人必怒。","丈人芒然毋自苦，暮四朝三栗难数。","舂有相杵，厩有厮养，击缶呜呜且高唱。","玉衡在空长十丈，称物深凭极其量。"]},{"t":"王昭君","f":"五言古诗","c":["凤皇虽为媒，鸩鸟能閒之。","美人在宫中，衾枕宁自移。","艳色自骄矜，安怪它人为。","当轩拜天子，流光耀前墀。","所愿在一见，去去无所辞。"]},{"t":"中山孺子妾歌","f":"古风","c":["桃华开春在双颊，縠衣稳称偏诸緁。","可怜中山孺子妾，流波转盼空光接。","情深不如线，穿珠不成串。","塘上对秋风，秋荷瓣瓣红。"]},{"t":"古有所思行","f":"古风","c":["吾闻大海之外环以瀛，其中之人不死不生。","十二应龙傥可乘，瑶象金虎来将迎。","文昌摄提共上下，南极一星时争明。","于嗟乎蜉蝣蟪蛄之世太短促，尔乃低头笑蛮触。"]},{"t":"久别离","f":"古风","c":["淅淅梧桐叶，几向秋窗落。","但见金井阴，欲朽银床索。","关河不必远，边山不必近。","乡心宛转托尺书，云中岂少南飞雁。","女萝与乔松，那得长相守。","君心傥弃捐，一日即为久。"]},{"t":"扶风豪士歌","f":"古风","c":["长虬不受泥束缚，神马何尝劳刻雒。","关中耳目龌龊多，未若扶风豪士信然诺。","将军能知郭解贫，季布肯赦曹丘恶。","黄金为注就君博，绝胜求田问舍苦不乐。","君不见平津侯脱粟饭，一过汲长孺，清浑一朝判。"]},{"t":"正月十有八日雪中奉使之绝塞","f":"五言律诗","c":["万里使穷徼，逡巡敢后期。","君恩试艰阻，母意重捐糜。","乡路马蹄缓，边风剑色移。","春城今夜雪，先已接龟兹。"]},{"t":"晚出居庸关","f":"五言律诗","c":["沙碛邻南幕，神京寄北门。","风云护天险，鼓角壮边屯。","故事防秋重，当时入寇繁。","圣朝今尚德，骑马度黄昏。"]},{"t":"青冢","f":"五言古诗","c":["绿柳寄春色，白草横边思。","累累北原冢，下有汉蛾眉。","艳色颇自重，图画能见欺。","近辞长门宫，远嫁单于儿。","闺闼逼左右，或误真妍媸。","妾意长已矣，君其慎来兹。"]},{"t":"瀚海","f":"七言古诗","c":["瀚海赤沙赤如赭，绵亘大漠无端倪。","星汉界天海界地，其广千里狭半之。","飞鸟解羽或傅会，游鱼蕴石良神奇。","红鹾曝日水咸苦，谓陆为海其以兹。","革囊载水乃可渡，不者人马皆渴饥。","汉家健儿数绝此，几人生全几人死。","海西落日大如轮，故鬼啾啾叫新鬼。"]},{"t":"天边美人行","f":"古风","c":["白水直上高山头，花草团作云锦毬。","六月气候如晚秋，天边美人清昼游。","金霞驻海凝不流，威凤十二相夷犹。","头上自有装，双椎大秦珠。","身上自有衣，半臂锦傅鞲。","高靴窄其靿，蟠龙郁相纠。","五花各有马，黄金为后鞦。","五石各有弓，青镞为箭鍭。","跽而野享团栾周，屠酥白酒裁新篘。","酒酣上马疾不留，脱辔飞上山之陬。","十八女儿骑橐驼，穿花渡水歌胡歌。","旃裘毳幕事征驮，胡雏束版为行窝。","异俗近古差复讹，阏氏劳苦殷见多。"]},{"t":"次法王寺","f":"七言律诗","c":["闻道羌胡化育难，今知日月照临宽。","云中天使回高节，道左名王献白纨。","万里梯航竞重译，百年旗鼓罢登坛。","群雏屏息牛羊队，指点威仪识汉官。"]},{"t":"废寺","f":"七言律诗","c":["山拥孤城草木荒，劫灰马首贡苍茫。","枭雏日落啼鸱吻，狐火秋阴上女墙。","碧藓半侵碑字黑，红罗犹缠佛金黄。","薛禅盛气包诸夏，不信多时旧物亡。"]},{"t":"塞上词 其一","f":"七言绝句","c":["雪消雁塞秋调马，月堕龙城晓控弦。","却自汉家飞将在，白头浑不识三边。"]},{"t":"塞上词 其二","f":"七言绝句","c":["白狼河南秋草稀，白狼河北夜霜飞。","沙场失却祁连塞，痛哭年年马不肥。"]},{"t":"塞上词 其三","f":"七言绝句","c":["绝国名王宠阿娇，舞衣歌袖薄红绡。","心贪关韨蒲桃锦，部落千山捕黑貂。"]},{"t":"塞上词 其四","f":"七言绝句","c":["对佛跏趺爇白檀，红袈裟映澹黄冠。","等閒不肯轻摩顶，脱帽时时拜可汗。"]},{"t":"塞上词 其五","f":"七言绝句","c":["秋风八月塞云飞，南北山头日合围。","一声吹彻黄芦叶，紫帽单于射虎归。"]},{"t":"塞上词 其六","f":"七言绝句","c":["灯火前营歇暮笳，阏氏小帐拨琵琶。","新声不踵明妃曲，霜月如烟下白沙。"]},{"t":"八月二日南归遇雪","f":"五言律诗","c":["人与沙头雁，南飞共此程。","捷凌初起势，喜和欲归声。","雪落单于垒，秋生上谷城。","梦中如识路，先慰倚门情。"]},{"t":"野草中得五铢钱","f":"五言律诗","c":["岂有光芒异，犹怜轮廓坚。","蚀深斑色古，渍少篆文全。","弃掷灵何在，摩挲臭尚传。","和亲娄敬策，输纳想当年。"]},{"t":"登泰山作","f":"古风","c":["日月分两丸，天地非完璞。","夜半古岱宗，浑沌独未凿。","云翻雾卷不可解，滚滚腾腾白如海。","层岩断壑沈欲尽，长松老栝皆安在。","蒿蓬飒然振，髣髴出神鬼。","客子当斯时，莫不股栗心震骇。","须臾日出扶桑东，玲珑万象开秋空。","一峰摇海色，众木号天风。","何处苍蝇之声来细微，乃彼鼍钟霜晓怒吼孤城中。","陟日观，眺云亭，之罘晓色何青青。","金泥玉检应替零，龙游翠葆都杳冥。","丰功盛德遍勒铭，谁能剥苔披藓读且听。","日向曛，客未去。","不见蓬莱之水清浅或可渡，片云飞落苍梧处。"]},{"t":"秋望洪泽湖","f":"五言律诗","c":["木叶洞庭下，秋涛洪泽回。","蛇龙今已放，璧马谩成灾。","苍莽空天合，沈吟晓望开。","防川有深戒，莫止岸加培。"]},{"t":"金山寺","f":"五言律诗","c":["众流合已尽，大海受其东。","万里峨眉雪，桃花晚涨通。","寺钟摇佛籁，帆影乱江风。","芳草齐梁恨，青青北固中。"]},{"t":"归棹","f":"五言律诗","c":["烟水萦归思，孤帆绕岸回。","村虚木未脱，秋迥雁将来。","客梦几时罢，江花昨夜开。","匡山如习隐，先筑读书台。"]},{"t":"挂剑台","f":"五言绝句","c":["徐君爱宝剑，公子爱寸心。","宝剑岂不贵，宝剑只千金。"]},{"t":"卢龙塞","f":"七言律诗","c":["策马九月卢龙道，卢龙塞头霜信早。","晚花高柳不作春，夕阳处处黄芦草。","客行系马且伫立，吹沙淅瑟边风疾。","黄芦叶叶皆抱根，低头三嗅黄芦泣。"]},{"t":"孤竹城","f":"五言律诗","c":["道出令支县，萧条东海浔。","如何多古思，烟草系人深。","臣主千秋案，乾坤不贰心。","传闻故祠在，立马一沈吟。"]},{"t":"澄海楼","f":"七言绝句","c":["长城掉尾入沧溟，城上飞楼插杳冥。","午夜妖狐作人语，不防曾有役徒听。"]},{"t":"红驼尼将军行","f":"古风","c":["皇不助乱，德正厥归。","爰命圣人，起东海垂。","长箭大马，惊雷飞霓。","比诸属国，一之扶义而西。","谓我是宁远冑牛。","赎我祖如五羊皮，赐名曰：宜汗纳。","实用志喜侍从左右，尝得参预密谋。","杏山峨峨，有雨祁祁。","尝此剋日，两兵交绥。","属有军事，有所指撝。","我祖白马，被红驼尼。","敌矢指击，戒骋勿羁。","桓桓我祖，按辔示暇。","军中不驰，来往数四。","得其要领，帝曰即马。","上闻徐之，日未移晷。","神策克敌，辙乱旗靡。","军中自是传红衣，将军辟易其大麾。"]},{"t":"拜远祖墓","f":"五言古诗","c":["广原何漠漠，千里横逶迤。","大河迎其东，长冈承其西。","中有远祖坟，五冢相肩随。","不知几何年，石马犹未攲。","方士厌王气，脉凿顶且灰。","镇金曾未渝，芒砀神龙飞。","岩岩泰山下，适得三公奇。"]},{"t":"过访沈葭士赋赠","f":"七言律诗","c":["款段城南不厌骑，风尘物色沈生奇。","国中几见真佳士，海内今称老画师。","白发下人贫殆甚，侧身怀古意常悲。","梁园久冷邹枚席，土锉年来只自炊。"]},{"t":"谒孟祠","f":"五言律诗","c":["横流不可遏，夫子树其防。","遗庙垂今日，令人增远望。","诗书资羽翼，雷电避光芒。","万古尼山色，青青接峄阳。"]},{"t":"咏存园玉兰","f":"五言律诗","c":["或有神灵意，经今四百年。","花明鬼火外，阴冷劫灰前。","不死岂殊性，孤生亦偶然。","江村一树雪，春色武陵边。"]},{"t":"壑庵","f":"五言律诗","c":["一壑藏春水，寒生清净心。","落花幽籁细，苦竹夕阳深。","寂以会众妙，澹然閒至今。","两湖三十里，于此寄微吟。"]},{"t":"过白沙泉适寺僧焙新茶因共啜之率尔成咏","f":"五言古诗","c":["金粉湖山色，争来画里看。","路从芳草入，泉爱白沙寒。","自率幽人性，谁知此境完。","松筠留静理，耳目易清官。","老衲事专一，新茶露乍乾。","等无差别味，直作水天观。"]},{"t":"林子归闽未果复至东齐赋赠","f":"七言律诗","c":["借问故人归去无，相逢摇落岁华徂。","寒衣未授关河冷，匹马重来海岱孤。","万户长安稀地主，三秋苦雨熟泥涂。","闽江回首音尘隔，不信南飞是鹧鸪。"]},{"t":"九日闻诸子登高诗以寄之","f":"七言律诗","c":["九月九日秋气深，天涯有客共登临。","可能一畅迷离眼，但恐徒伤迟暮心。","上国穷檐仍旅食，高江渔唱失乡音。","倦游司马尤无赖，四壁萧然渴病侵。"]},{"t":"秋尽","f":"七言律诗","c":["霜清九月飞鸿急，秋尽孤城捣练哀。","多病及今常伏枕，销愁何处独登台。","阳收生理行将伏，岁逼寒阴又一回。","玉剑绛衣贫不办，舍人甘老厩中才。"]},{"t":"偪侧","f":"七言律诗","c":["旧游历乱等空华，寄客深居水一涯。","猗傩此生输草木，逶迤吾道付龙蛇。","微尘偪侧终容物，故业萧条已丧家。","乐与田夫近相狎，扶风幽事托汧罝。"]},{"t":"送别钟匪莪","f":"五言律诗","c":["征马顾还嘶，飞蓬东复西。","伊予甘落落，吾子慎栖栖。","海内谁胶漆，边陲正鼓鼙。","相依傥严武，好住浣花溪。"]},{"t":"闻雁","f":"五言律诗","c":["白月转庭树，清霜下井干。","一声哀雁起，千里大江寒。","凄听宁偏入，离忧自万端。","乾坤吾与汝，前路共漫漫。"]},{"t":"渡滹河","f":"五言古诗","c":["朔风杀边草，肃轸凌寒晨。","稍稍霜积渚，暖暖月落村。","滹沱冰未合，两涘牛马喧。","方舟中夷犹，榜歌何所陈。","龙蛇窘仓卒，日月晦中天。","惊波和促节，忼慷微音宣。","时命有通蹇，下士复何言。"]},{"t":"井陉口","f":"七言律诗","c":["骏马蹶蹄仆茧足，怪石人立水鬼哭。","可怜天险不足守，泜上谁能救败衄。","旗鼓当时度汉军，苍茫天意厌瓜分。","英雄独袭神龙迹，汉主终遗广武君。"]},{"t":"太原行","f":"七言古诗","c":["甲申天崩明不腊，九庙神灵哭阊阖。","嚆矢由来启仁圣，我祖鹰扬委身正。","金戈铁马气轶群，往往传避飞将军。","太原言言贼城守，矢石如山计持久。","蔽身土簏一何怯，被羽先登老谋捷。","明月不见旧牙旗，寒雁乱下汾河湄。"]},{"t":"历下亭","f":"七言古诗","c":["鹊湖风厉水拍堤，菰芦冻折渔梁危。","天寒鰦鷠不复跃，目落鵁鶄时自飞。","渚烟苍苍沙历历，中有虚亭俯空碧。","长廊诗句光怪多，杜陵野老留遗迹。","芜没千秋谁再新，直栏横槛压波纹。","月明四面渔歌起，争唱齐州李使君。"]},{"t":"西甘涧赠藏山上人","f":"七言律诗","c":["颓云古石秋森森，半椽懒卧西溪深。","藏头既白人不识，岩花寒證琉璃心。","石龛如斗凭虚起，一弄丝桐百昌喜。","芒忽谁开太古音，木叶夜下琴泉水。"]},{"t":"哭松山六弟","f":"五言古诗","c":["生者不可知，死者忽漫灭。","清晨携我手，薄暮成永诀。","秋风尔何心，吹我右臂折。","褰衣复其魂，一叫气三咽。","斤斧戕五中，寸寸争割裂。"]},{"t":"五岁逐队嬉六岁踵相逐七岁八岁时揽腕出就塾故物宿昔逢神解一何速镆铘愧丝整豫章超朴樕谷风陨秋霜寿命何局趣血涕塞我吭吞声不成哭","f":"五言古诗","c":["兄弟虽至亲，聚首曾几何。","晨风有征翼，逝水无停波。","相逢盛年尽，老大仍媕娿。","生为长相思，死为永别离。","谅无子桑识，馀响寄安歌。"]},{"t":"孟冬晓发之闽南","f":"五言古诗","c":["飞蓬岂无根，鸿雁亦有侣。","霜折就衰心，风乱随阳序。","膏车蚤戒徒，贱客易行旅。","踟蹰老马心，仓皇仆夫语。","萧萧野原草，淅淅寒林雨。","漫漫江海遥，眇眇独愁予。","北平苦数奇，漂荡终安取。"]},{"t":"雪","f":"五言古诗","c":["我生匪兕虎，乃与旷野俱。","束发绝大幕，二十临淮徐。","江湖系人迹，今者犹饥驱。","飞蓬实自振，飙风汝何诛。","寒雨变雪霰，层冰合泥涂。","周行昧己失，行李杳绝无。","将投逆旅息，主前辞仆夫。","岂不敬爱客，秣马无生刍。"]},{"t":"寒","f":"五言古诗","c":["夜漏未告终，星芒动昏野。","朔风振冻木，潇潇残雪泻。","晶晶大泽冰，的的远村火。","独客久服劳，酸嘶闵予马。","繄予竟何辜，动无尺寸假。","谁为汧澼絖，治我龟坼可。","志定势自移，坦夷见埳轲。"]},{"t":"晓渡扬子江","f":"五言律诗","c":["平楚渺无尽，乱山寒欲苍。","北风吹片席，此际一相望。","客久增恇怯，吾哀罢慨慷。","烟蓑依雪渚，江上有渔郎。"]},{"t":"钱唐江","f":"古风","c":["放蛇大泽中，蛇且化为龙。","搏虎江水头，虎竟败于牛。","馆娃宫中歌吹低，惊涛一旦浮鸱夷。","锦袍白马北伐齐，夜有鹧鸪沙上飞。","钱唐江，江水深，水有波，人有心。"]},{"t":"晚泊清紫港","f":"七言律诗","c":["断雁轻鸥共渺然，殊方此夜客愁偏。","可怜寒角为谁苦，何处孤帆且自悬。","水气欲生山嶂雨，天风不散石林烟。","世情老大都心折，倚棹空江独火前。"]},{"t":"富春濑","f":"五言古诗","c":["天鸡矫其翼，潜虬鼓幽吹。","旦气肃高空，扁舟富春濑。","林虚万窍作，峡窄层阴渍。","贞松表亢节，孤云任偏智。","咄咄毋相迫，人生各有志。","高躅接视听，遐心邈汪濊。","愧兹纆牵长，轗轲为形累。"]},{"t":"捕鱼","f":"七言古诗","c":["江潭之水琉璃碧，折苇残萧寒摵摵。","縠波细叠峡风回，沙雨低飞渚烟积。","横江截网网目张，大船小船环鸣榔。","哀壑空响传丁当，冯夷罔象皆遁藏。","呀嚇鰋鲤丽鱮鲂，轻鯈纤鲋难数量。","红腴青颅纷杂沓，尖头舴艋苦迫狭。","一岁生理一日尽，归路渔歌笑相答。","前汀新月一钩起，重悲泼刺鱼跳子。"]},{"t":"雨中上仙霞岭","f":"七言古诗","c":["黄须野客好服奇，高冠长铗纷陆离。","龙沙惨澹海月碧，匹马往者尝东西。","三十飘萧鬓毛秃，乾糇易果饥驱腹。","掉头更作万里行，岁晚蛮山杖秋竹。","蛮山峨峨闽越界，控海横江森仄隘。","一峰遒紧群峰颓，百物从之出奇怪。","赤松蜿蜒复蚴蟉，怪石横叠于菟首。","暝翻白日雷霆惊，冷戛霜空神物走。","高寒薄天朝气变，出云入云看不见。","双屐茸茸踏石花，但觉阴森湿人面。","淫蒸土下互温冽，高处阴风吹作雪。","玲珑玉树披素华，枝叶碎凿秋冰骨。","土囊势张风力峭，刁刁调调号百窍。","鼪鼯乱窜鸺鹠叫，深潭沈沈窟龙啸。","斯须冥漠万壑沈，急雨扑灭山头烧。","野客抵掌发狂笑，此游差快殊不料。"]},{"t":"旅夜","f":"五言律诗","c":["江月当人起，烟沙近腊天。","不知今夜梦，可到故林边。","敝罶三星在，扁舟百丈牵。","浮生厌漂荡，四十转茫然。"]},{"t":"雨","f":"五言律诗","c":["急雨鸣清旦，寒山湿翠屏。","岸沙淤虎迹，潭水郁龙腥。","万事方纠结，孤篷复晦冥。","客魂真断尽，不独怨伶俜。"]},{"t":"日本小刀歌","f":"七言古诗","c":["青天疾闪金蛇电，冷光激射双目眩。","熟视乃是日本刀，匣底阴森沈一片。","委委蛇蛇刃九曲，软许吹毛坚切玉。","古斑深蚀蛟血腥，细理饱湛龙文绿。","暹罗花缬裁作囊，陇山鹦鹉刻作杷。","万方珍重无所用，鬼哭秋灯风雨夜。"]},{"t":"洋琴歌","f":"古风","c":["岛中之木名莫知，饮霜饫露凡几时。","良工断之解作片，片片声中青玻璃。","日雕月磨沃以漆，黝黝玄光横四尺。","空中坦外如几平，四匝寻之无寸隙。","斯须盖启金枢转，霏微花色蠃纹施。","玉柱密插蟠螭身，凤眼低嵌雕龙片。","银丝双弦二十六，一弦一声声胜肉。","别琢香檀曲拨多，经纬纵横弦下伏。","弹弦无事须银甲，但将檀拨轻挑压。","满耳琤璁弦上鸣，不知宫调何由洽。","初弹参差殊细微，女儿私语翡翠帏。","铿然一转得秀整，罗裌慢摇金钏冷。","三转四转曲入破，苍岩石罅幽泉过。","嗈嗈嗷嗷沙雁惊，急雪乱搅飞花堕。","轻淫妖艳风习习，曼声浮荡新声涩。","碧眼蛮工一再弹，欷歔北客天南泣。","吾闻中国圣人之，乐和且平抑扬清。","浊皆正声洋琴尔，慎毋多鸣使人不识初古情。"]},{"t":"瑞竹岩","f":"七言古诗","c":["岩口飞来一片石，㟏岈低压危岩坼。","时有山僧杖履过，紫藓阴阴入行迹。","一转不知身已高，长松古桧如鸿毛。","海天苍茫泼绿黛，列岛群洲都细碎。","日暮徜徉谁与期，满屋流云围石碓。"]},{"t":"皋亭山","f":"五言古诗","c":["大江夜兵下，秋满皋亭山。","炎精谢金气，形胜馀江关。","国步一以移，天地皆拘挛。","君子匪异人，忠义任我肩。","策以淮东西，尺土封狂澜。","城上刁斗急，城下心胆寒。","制置无贰心，丞相翻奸顽。","坏木不可支，信矣先民言。","江风吹木叶，瑟瑟鸣悲酸。"]},{"t":"青溪词","f":"五言古诗","c":["箐林不受日，岁晚狐狸生。","始盬死人脑，起啖生人睛。","能使都邑中，踪迹皆纵横。","我欲寻其原，贵得阴阳平。","往者青溪洞，三穴谁私营。","揭竿岂其性，皆我良庶氓。","大将军征诛，功名良足轻。"]},{"t":"渔梁驿","f":"五言古诗","c":["伏莽塞荒蹊，尺寸苦偪仄。","鞍马不通江，山舆受行客。","舆夫时时歌，译之不可得。","雨雪冒南交，前过渔梁驿。","驿水荡白沙，中有败锋镝。","传闻韩将军，于此禽二逆。","殿前两虎贲，先期中神策。","刲羊而召狼，徒伤武夫力。"]},{"t":"木绵庵","f":"五言古诗","c":["野樵误行人，引客入庵路。","暝色何苍苍，庵昏木绵树。","请客立斯须，为客陈其故。","树下陈死人，庸昏积成误。","血痕惨不灭，千秋著馀污。","可怜葛岭下，蟋蟀吟朝露。"]},{"t":"雨夕登浦口楼望金陵作","f":"五言古诗","c":["暝色下殊方，登楼风雨夕。","悠悠乱江鸿，黯黯怀乡客。","凭高运晚睇，苍莽分阸塞。","峨峨金陵城，石头踞其侧。","微鼓出昏烟，风灯动樯隙。","古情迫中发，人事羌何极。","迁化理自然，不啻潮与汐。","客涂多悲心，青阳移晚色。","思深物莫敚，涕下临江篴。"]},{"t":"项王祠","f":"古风","c":["白蛇断，乌骓穷，海内莫敌隆准公。","百二小儿歌沛中，霸气汩没三户空。","眼中成败势即判，大王叱咤终英雄。","楚云沈沈压祠宫，千秋伏腊犹鼓钟。","鼍龙叫啸宝剑血，草木惨澹灵旗风。","乾坤失意丈夫泪，大江日落寒涛东。"]},{"t":"悼离篇哭亡姊","f":"古风","c":["吾家少姊类吾母，婉慭从容有所守。","儿时颖慧能读书，列女篇章皆上口。","锦官城下锦江水，芙蓉红压锦城里。","当时姊弟并孩提，朝朝联臂芙蓉底。","姊挽老父带，弟牵慈母衣。","终年不一出闺阁，无日或复离庭闱。","长安归后互分飞，姊行作妇弟娶妻。","膝前儿女各已长，眼中二老嗟安归。","滂沱血涕昔对下，天乎为此死别离。","凋丧十五年，存者五六人。","齿发日已老，骨肉情愈亲。","如何零露意，又使芳华泯。","屈原无人詈婞直，骆统困约谁分食。","吁嗟骨肉不再得，哀猿一声泪填臆。","萧森雨气逼昏灯，灯灺更长天墨黑。"]},{"t":"哭浚儿","f":"七言古诗","c":["眼中无复有我子，号哭三月此心死，天乎哀哉有如此。"]},{"t":"夜","f":"七言律诗","c":["感时又见清秋暮，吊影其如永夜何。","尝苦风灯依壁尽，非关霜杵隔邻多。","醉乡无力降愁域，空法何年割爱河。","回首延陵遗恨在，千秋嬴博厌经过。"]},{"t":"次韵答赠刘东郊","f":"七言律诗","c":["名刺消磨短袖中，疏狂直与古人同。","独来穷巷知何好，深喜青尊且未空。","一夕寒灯疑梦寐，十年长剑哭英雄。","惊乌断雁休相乱，好听邻鸡唱晓风。"]},{"t":"邱家岸雨中晓渡","f":"七言律诗","c":["客子出门天欲旦，晓寒不增春已半。","杏花微雨济上村，白沙浅草邱家岸。","古渡萧条人迹稀，乱流敢惜沾裳衣。","篙师拥楫谩相劳，底事风波汝不归。"]},{"t":"老鹳","f":"古风","c":["㟙山之石铁色古，上有孤楠枝叶疏。","风吹音响日萧瑟，南飞老鹳来号呼。","海门阴阴雨气腥，毛衣中夜愁沾濡。","危梢高栖形影孤，胡不整翼归哺雏。","君不见秃鹙之喙长一尺，人立石梁饱鲜鲫。"]},{"t":"重寓准提精舍感赋","f":"五言律诗","c":["客有风尘者，飘然天地中。","重来沧海上，直在故园东。","芳草映华发，孤云覆断蓬。","精蓝诸品净，独与旧时同。"]},{"t":"灭没","f":"七言律诗","c":["浣花溪头花不如，富春江上树犹疏。","世情已落金张外，生理聊凭枣栗馀。","鹳鹤栖迟丛莽杂，鱼龙窟宅大江虚。","虞卿懒作千秋事，灭没穷愁旧著书。"]},{"t":"初伏日","f":"七言律诗","c":["伏金积火畏相和，溽雨蒸云日几过。","倚杖风尘回首近，开尊节序去人多。","乘除有在心焉托，出处无方鬓待皤。","暝色欲来岩翠黑，欷歔山鬼泣烟萝。"]},{"t":"怀友人","f":"五言律诗","c":["射虎将军后，蹉跎坐白头。","寸心持报国，多病习伤秋。","霜雪苍鹰疾，关河老骥休。","西风吹望眼，独倚仲宣楼。"]},{"t":"闻钟匪莪留滞登州赋寄","f":"七言律诗","c":["衰草寒云海戍昏，秋风晓角镇城喧。","几挥老泪田横岛，独系乡愁白下门。","烈士数奇矜晚节，穷途心折慎新恩。","音尘寂寞时将晏，目极齐东一断魂。"]},{"t":"哀雁行","f":"七言古诗","c":["折芦萧萧秋渚空，沙头旅雁鸣嗈嗈。","虞罗寻声横相及，比翼那复联雌雄。","清霜碧月苦回首，只影惨澹归鹅笼。","庖厨幸免机肉厄，萧寺乃休馀粮供。","夜分故偶远相觅，招呼两两凌苍穹。","欲起不起自投地，败翮谁借毛羽丰。","哀号百转肠寸截，云泥咫尺终难从。","从之不得继以死，此义鸟畜时能通。","阶除忍草晓悽碧，血染杜宇成殷红。","吁嗟微禽克有终，马牛龌龊差其风。"]},{"t":"再赋哀雁","f":"古风","c":["故雄失，故雄惊，魂那相顾脱身矰。","缴外可以高飞去，故雌失故雄大义。","固不夺馀生樊笼，外可以幸存活北。","风萧萧，新月黄，一飞一栖心摧伤。","寻声察影务相得，哀怨一和天飞霜。","寸肠叫绝血泪继，以死报雄何慨慷。","雄可语患难，雌可语死生。","江湖寥落烟波里，似续空山麟凤名。"]},{"t":"初春寄西涧上人","f":"五言律诗","c":["残雪东皋尽，田盘寒翠深。","所怀虚岁月，之子遂飞沈。","夜水移琴兴，春风活道心。","蹇驴仍好在，行向涧西寻。"]},{"t":"拜意师墓","f":"七言律诗","c":["去年执别清溪头，今年寂灭归一丘。","尘中穷达徒相乱，眼底存亡亦太浮。","古洞青萝春黯黯，野田黄雀晓啾啾。","客长贫贱亲知少，容易潸然涕泗流。"]},{"t":"就藏上人乞花木栽草堂前戏效少陵体 其一","f":"七言绝句","c":["茅斋敞开丘壑拱，石径曲绕芳菲稀。","熟知野兴几人得，忍使春风转眼归。"]},{"t":"就藏上人乞花木栽草堂前戏效少陵体 其二","f":"七言绝句","c":["鹅儿艳艳轻黄吐，凤子茸茸浅碧开。","不信石屏南麓畔，杂花小卉独栽培。"]},{"t":"就藏上人乞花木栽草堂前戏效少陵体 其三","f":"七言绝句","c":["闻道红香属对桃，攲斜留影照溪毛。","肯怜仅落萧条剧，敢惮春锄树艺劳。"]},{"t":"就藏上人乞花木栽草堂前戏效少陵体 其四","f":"七言绝句","c":["海棠更倚断坪西，带雨凌风一向低。","莫止留连众香国，也应点染浣花溪。"]},{"t":"寒食","f":"七言律诗","c":["廌青山堂邻涧阿，应门白沙连碧莎。","乱山寒食落花路，返照风磴樵人歌。","古意萧然未泯灭，春华好在毋蹉跎。","郤超远趣不易得，寂寂剡溪今若何。"]},{"t":"上巳日龙泉寺看花作","f":"五言律诗","c":["禊事阑亭歇，幽情野寺偏。","松云横一杖，花雨洒诸天。","日午阳和足，山深造化全。","百年浑遣兴，随地得悠然。"]},{"t":"秋分前一夕集五石瓠堂小饮剥栗因以秋分二字为韵送别刘子东郊 其一","f":"五言律诗","c":["藉促残灯膝，深谭剧未休。","俗情惊卓荦，古意见绸缪。","酒咽长贫泪，天归短鬓秋。","邺城烟草合，风雨滞应刘。"]},{"t":"秋分前一夕集五石瓠堂小饮剥栗因以秋分二字为韵送别刘子东郊 其二","f":"五言律诗","c":["震泽莼何似，渔阳栗旧闻。","望乡仍寄食，习隐未离群。","歧路飞蓬熟，清愁远梦分。","关河摇落候，半是不归云。"]},{"t":"藏上人寄诗招游西涧以事不果赋此却寄 其一","f":"七言律诗","c":["匡庐秀色田盘得，亦有幽人继远公。","日暝龙蛇潜大壑，天清鹳鹤振秋风。","味齐甘苦休尝舌，心了方圆任凿空。","枯寂年来晦踪迹，夕岚朝翠共冥蒙。"]},{"t":"藏上人寄诗招游西涧以事不果赋此却寄 其二","f":"七言律诗","c":["石路逶迤西涧西，碧霄真拟蹑丹梯。","风烟百里裁相接，云水终年或竟迷。","落日孤筇频伫立，新诗几叶任封题。","尘中老眼昏成瞀，安得金鎞一借携。"]},{"t":"藏上人寄诗招游西涧以事不果赋此却寄 其三","f":"七言律诗","c":["管乐功名久不磨，孤生天地鬓双皤。","脱身愿作无终隐，好事休推有道科。","万里东西蓬尚转，百年夙夜露仍多。","骅骝鶠雀都无著，白水青山奈汝何。"]},{"t":"因藏公寄东涧开士","f":"五言律诗","c":["不染缁尘色，吾师独讳名。","道存山木脱，心死谷云生。","更有忘机侣，都无适俗情。","近闻新甃毕，日日事茶铛。"]},{"t":"哭所知 其一","f":"五言律诗","c":["百死唯天命，千秋信苦吟。","灌夫徒尚气，优孟绝无心。","莫更求完卵，知应覆短衾。","青灯风雪甚，幽梦隔穷阴。"]},{"t":"哭所知 其二","f":"五言律诗","c":["子作巴猿哭，长音塞雁闻。","异乡谁料理，行路致殷勤。","白日累臣罪，黄沙志士坟。","泥涂无限泪，沈痛一呼君。"]},{"t":"天城寺","f":"五言古诗","c":["束发牵世纲，衰谢仍漂摇。","往迷泥涂步，今回尘外镳。","遣此殷忧况，□值芳春朝。","灵区贡隈隩，净域栖寂漻。","飞轩面空翠，丹壁摩青霄。","肃肃山翟飞，趯趯鼯鼠跳。","塔铃语真呗，松雪洒惊飙。","万化无端倪，无生自逍遥。","委形诚斯须，挥手谢松乔。"]},{"t":"晚过天城寺看老梅","f":"五言律诗","c":["寒勒将舒蕊，春苏半槁根。","孤清真欲绝，迟暮复何言。","幸与岁时久，深叨封植烦。","低回对虚馆，山月共黄昏。"]},{"t":"上方寺 其一","f":"五言律诗","c":["独隔层岚迥，今知细路深。","一时移耳目，万象变萧森。","古拙居人服，偏私造物心。","天门双日月，随意自升沈。"]},{"t":"上方寺 其二","f":"五言律诗","c":["风磴残云外，虹梁瀑水西。","险愁岩石堕，冷逼洞猿啼。","白日行如梦，青天瞰欲低。","上方信幽绝，消得昔人题。"]},{"t":"支离叟二松歌","f":"七言古诗","c":["物有奇伟每绝伦，意想所及犹非真。","乾坤乃有此松树，被发狂叫惊天阍。","何如于此诡托根，皴皮斑駮苍龙鳞。","千年偪侧忽怒伸，娲石迸裂青天痕。","风雷倒激铁干偃，日月低荡秋阴昏。","下有一株不盈尺，连蜷夭矫蟠龙孙。","二者夫谁是化身，伸缩大小真有神。","诸松鹓鶱复凤翥，视此一切非其群。","形神直追古苍颉，冠剑俨对荆灵均。","阴森不敢久相逼，鬼物呵护如欲嗔。","委蛇却下恣太息，回首一峰沈乱云。"]},{"t":"盘泉","f":"五言古诗","c":["岩壑无定姿，絪缊变清旦。","胜因引纡步，得趣成汗漫。","微暄解作近，芳意甲坼先。","松丘郁蓊蔚，兰阪虚葱茜。","荧荧和景鲜，活活激响乱。","偶逐岩下云，遂及垂虹涧。","叠石纷阸塞，飞流莽洄旋。","境远神俱冥，赏真理独见。","近服任公训，熟与海鸥玩。","盥手弄鯈鱼，游心同伴奂。"]},{"t":"自少林至西静室","f":"五言古诗","c":["老鹳欬密林，猛虎蹲伏莽。","黝黝亭午阴，翏翏太空响。","旷怀无前期，高兴肄独往。","化城周大千，维摩室方丈。","布毛證鸟窠，妙谛飞龙象。","傥非水精域，焉启鸿荒想。","纵心以天游，六凿罢相攘。"]},{"t":"指石行","f":"古风","c":["田盘山中尽玄砺，险怪离奇出思议。","柱师短杖惯冥搜，披葛扪萝亲指示。","玉指一双拄厓际，浑融雕琢真殊致。","夔魖辟易罔象藏，半天挥拂云霞坠。","或者牟尼初度时，此是当时第一义。","我来睇视心郁纡，良久摩挲古苍翠。","安得力士移置神尧阶，区别忠佞无隐怀。"]},{"t":"送别周西穆","f":"五言古诗","c":["神马不受羁，慈乌方告哀。","栖栖远游子，握手长河隈。","缟衣照斑鬓，色惨神不颓。","萧索天鸡翼，磊砢豫章材。","清超见真挚，简易名理该。","空波漾返景，归棹行相催。","敢恤川涂别，所念音尘乖。","身无双飞翼，送子以鄙辞。","东海还牧豕，北山聊凿坏。","毋滋陵阳泣，璞玉慎所怀。"]},{"t":"和刘东郊五石瓠堂夜坐怀西涧藏公","f":"五言律诗","c":["一雁叫云碧，乱山今夜秋。","若无良梦寐，何以对林丘。","虎气吹沙冷，萤光拂水幽。","坐知灯火下，也自忆玄州。"]},{"t":"落叶","f":"五言律诗","c":["西风吹故林，一叶一秋心。","生理或未尽，暮愁相与深。","因知白发者，中有老怀侵。","独立斜阳外，君听感倡音。"]},{"t":"有所思","f":"五言律诗","c":["海门开返照，烟景入萧森。","秋草晚犹绿，相思深复深。","鹿卢沈宝气，山鬼啸穷阴。","白发终贫病，苍茫天地心。"]},{"t":"寄杨青眉","f":"七言律诗","c":["情谊与君如雁行，漂摇急为定行藏。","一身投老乾坤窄，八口熬饥日月长。","衰废敢嫌吾道直，孤贫端信友生良。","由来货殖龙门传，别有深心寄慨慷。"]},{"t":"墓祭作","f":"七言律诗","c":["伤心此日墓门边，风树衔悲廿四年。","食客尚能谈往事，蜀人真不负生全。","采诗绝徼闻淳俗，遗像千秋实异传。","相对失声同一哭，峡云蒲水两茫然。"]},{"t":"暮春雨中备三侄以骑邀迎过宿其山庄","f":"七言律诗","c":["泥滑新莎路曲盘，花飞晓水气清寒。","栖迟苦厌常攲枕，顾盻犹能一据鞍。","雨色欲淹春索莫，马蹄不限步艰难。","亦知痴叔痴应绝，倒著山公醉后冠。"]},{"t":"春郊雅集诗 其一","f":"五言律诗","c":["小集宜群季，春游喜北陂。","一觞愁亦尽，四矢昼能移。","晚日明皮鹄，微风叫饿鸱。","将军推善射，不信数仍奇。"]},{"t":"春郊雅集诗 其二","f":"五言律诗","c":["柳碧关南路，花飞郭外村。","时平边候少，寺古佛灯昏。","取醉忘衰病，行歌有弟昆。","百年多聚散，此会莫轻论。"]},{"t":"乞米东邻僧","f":"七言律诗","c":["起来烟火断山厨，乞米东邻亦太迂。","龙树久知离挂碍，鹿门犹恨有妻孥。","古情质直忘宾主，法界虚空灭有无。","一钵斋粮聊给日，慈悲能济范莱芜。"]},{"t":"孤村","f":"五言律诗","c":["一杖全吾道，孤村见古风。","理看生育遂，俗尚有无通。","瘠土民无逸，山田岁不丰。","侧身空谷底，天意放愚公。"]},{"t":"接插","f":"五言律诗","c":["毋为恋旧林，别假一枝阴。","忽凿自然理，翻知造物心。","异根能作合，非种莫相侵。","君看芝兰室，其中渐染深。"]},{"t":"树架","f":"五言律诗","c":["微生竟何托，弱蔓引青丝。","树立徒悲汝，扶持独在兹。","雨深如欲泣，风急谩相吹。","谁念南山柏，孤撑性不移。"]},{"t":"夏至又雨","f":"五言律诗","c":["不识皇天意，空怜小麦秋。","眼穿看垤蚁，心苦辨林鸠。","烟火迟方举，云霓湿未收。","腐儒甘饿死，今日为谁愁。"]},{"t":"纳凉","f":"五言律诗","c":["层阴延暮色，秋水逼庭中。","云作他山雨，蝉吟灌木风。","固知双鬓薄，且得寸心空。","浩荡乾坤里，虚舟路不穷。"]},{"t":"喜麦熟","f":"五言律诗","c":["野色开千顷，炊烟起万家。","夏衣饥不典，村酒薄能赊。","帝力信何有，民生良可嗟。","无端种瓜叟，起舞葛巾斜。"]},{"t":"若水上人禁足东涧以诗寄我赋答","f":"七言律诗","c":["孤云隐见终无相，野水东西不定方。","丈室风幡原自动，诸天龙象俨成行。","尘沙障眼谁先觉，羁绁牵人久异乡。","禁足一时参妙悟，眉间早示白毫芒。"]},{"t":"咏山花","f":"五言律诗","c":["离立宁标异，孤芳殊众材。","秋山深夜雨，临水一枝开。","汝幸无名字，犹防有折摧。","沅江香草暮，谁寄楚臣哀。"]},{"t":"同西涧藏公重过野寺茗饮 其一","f":"五言律诗","c":["摇落穷秋后，山寒木叶深。","短筇乘野兴，缓步得幽寻。","只是他时事，真成隔世心。","再来陈迹扫，孤磬起清音。"]},{"t":"同西涧藏公重过野寺茗饮 其二","f":"五言律诗","c":["道侣时相见，山翁许共过。","茗柯能悟入，芥子有包罗。","影覆慈云暖，香生忍草多。","辩才今钝拙，无事怯维摩。"]},{"t":"同西涧藏公重过野寺茗饮 其三","f":"五言律诗","c":["不设禅□械，茅庵拥碧沙。","狙公秋拾栗，山鬼夜簪花。","虚白了无染，寒阴半欲遮。","未能心转物，每到辄忘家。"]},{"t":"观村人刈稼","f":"古风","c":["山村数家面山处，屋茅不葺篱不补。","冬春槺覈暂糊口，有日桑阴閒臼杵。","秋风西畴熟新黍，大儿转碌碡，小儿涤场圃。","老农伐薪妇轑釜，里正跨驴来击户。"]},{"t":"秋分日雨后盘僧致牡丹四本酬予书植诸新松之侧罗罗清疏映带可目喜而赋之","f":"七言律诗","c":["腕底书成泣鬼神，黄庭历劫本犹真。","乃翁捉笔非能事，细雨分花实胜因。","生理敢希千树橘，醉乡端藉数枝春。","白沙芳草毋相污，接洽新松好比邻。"]},{"t":"溟涬歌","f":"楚辞体","c":["山之荡兮水之洄兮，阒其同溟涬兮，何羭之来予攘兮。"]},{"t":"野步口号","f":"七言绝句","c":["暮山秋水澹横姿，拄杖乘閒野步迟。","清响一声崖栗堕，笑看鼯鼠暗跳枝。"]},{"t":"九日登东冈小女为予簪花烹菊留连竟日戏作","f":"七言古诗","c":["水色不敌漻天清，霜信欲逐凉飙生。","时当九日那易得，兴发一旦谁能绳。","次公清狂醒亦作，孝绪隐迹心兼并。","取复不远他日侮，怜我无已娇儿情。","黄花碎撷插斑鬓，苦菊细瀹吹破铛。","野游汗漫动成趣，老态拥肿何庸憎。","鸿飞江海信寥阔，鼎食钟鼓徒铿鍧。","忽焉遥岑下落日，或恐阴壑来山精。","一树一石神物附，秋蛩秋鸟天和鸣。","苍山白水幸自力，天寒岁暮予汝凭。"]},{"t":"冷子示关中友人赠诗且索予作赋此以赠","f":"七言古诗","c":["吾闻关中建瓴势，襟带山河雄百二。","名贤大儒每挺出，吾道苍茫实攸寄。","峥嵘馀气未肯伏，有时更出英雄辈。","多君壮年多壮游，锦囊古剑临清潜。","一康三李假光怪，太华终南泄灵秘。","我行海内十有八，老马风尘消故智。","迄今关雁起秋风，把酒危楼辄西睇。"]},{"t":"西宁令洪时懋见过赋赠","f":"五言律诗","c":["衰废勿复道，寸心怀国恩。","相逢无厚薄，努力尽深言。","沙碛黔黎苦，边城风俗惇。","君如敷德化，抚字莫辞烦。"]},{"t":"立春日夜冷吉臣招饮","f":"七言律诗","c":["相看落落无交亲，相赏由来自有真。","尺幅定传千古迹，醇醪能醉独醒人。","家迷碧海萍踪眇，路失金门雪鬓匀。","明月寒灯同此夜，老怀约略受春新。"]},{"t":"讯天城寺梅信兼柬藏公","f":"七言律诗","c":["山寺老梅近何似，昔年逋客记幽寻。","相逢一唤春愁醒，自许能知古意深。","驴背风尘将寸柬，夜来冰雪搅离心。","藏公独具真情性，几绕寒香作野吟。"]},{"t":"山庄对雪","f":"五言律诗","c":["片月落寒白，微风生近林。","不知侵晓雪，已压四山深。","太素还群有，虚灵见寸心。","丘琴尽清散，一弄水龙吟。"]},{"t":"咏史五绝句 其一","f":"七言绝句","c":["八百诸侯自会同，戎车载主白旄东。","海滨二老嗟安在，薇蕨青青暮雨中。"]},{"t":"咏史五绝句 其二","f":"七言绝句","c":["风扫寒云紫塞开，长城雪后白成堆。","自伤老眼昏尤甚，疑是秦人骨未灰。"]},{"t":"咏史五绝句 其三","f":"七言绝句","c":["白马雕弓气岸然，秋风射虎南山边。","匈奴十万愁飞将，慎莫相逢醉尉前。"]},{"t":"咏史五绝句 其四","f":"七言绝句","c":["邺城烟草镇漫漫，兄弟操戈六郡残。","不信卢龙古边塞，一时有路入乌丸。"]},{"t":"咏史五绝句 其五","f":"七言绝句","c":["渔阳羯鼓声惨悽，一曲霓裳万马嘶。","剩有剑门西岭雪，年年常待翠华西。"]},{"t":"招同藏公过万松寺看牡丹作","f":"五言古诗","c":["春草弄芳色，相思欲何言。","孤琴不成调，脱身寻丘园。","新新无已时，迟莫将谁援。","火传薪指穷，兹理如所宣。","软吹起客心，问彼尘外缘。","何以契道怀，棼杂或不牵。","行歌入沕穆，杖笠任后先。","真境匪远趣，隈隩金绳悬。","宝华湛琉璃，白日丽轻烟。","翠鸟试翾飞，威凤稍低鶱。","诸相固纷糅，繄谁得其原。","妙香粹无著，畅悟无生前。"]},{"t":"咏法藏寺古松","f":"五言古诗","c":["造物无馀力，孤生此物奇。","钩盘容一骋，局促殆相持。","骨耸青麟角，斑丛赤豹皮。","雷声如解作，龙战不披靡。","势薄秋空黑，根蟠大壑危。","长风有时下，万里为之吹。","孔盖邀天步，金铜助佛仪。","介龟终解甲，灵怪亦何为。"]},{"t":"牧牛精舍成同人落之","f":"五言律诗","c":["近期除物役，宁敢背诗书。","吾道无歧路，微生托此庐。","白头消日月，真意会禽鱼。","何似辟支老，初为树下居。"]},{"t":"闻石东溪昆季远辱过访东溪疾作而返赋此志谢","f":"七言律诗","c":["青山白发两如何，一室乾坤独寤歌。","野老一甘成寂寞，巾车不信有经过。","鱼龙异数文章在，贫贱侵人感激多。","病起秋风重相访，浊醪亦足慰蹉跎。"]},{"t":"三泉寺","f":"七言律诗","c":["此地经临几劫灰，日高鸟鼠遍香台。","横陈灌木谁亲植，无赖黄花春自开。","老衲忘情人事废，乱泉如语客心哀。","暮山飒飒飘风雨，不见明昌射猎回。"]},{"t":"漫兴","f":"五言律诗","c":["幽意复谁知，斜阳杖一枝。","好山存古色，荒稼给生资。","蠖屈清贫得，鸡栖老病宜。","寸心殊不折，陡健日裁诗。"]},{"t":"初秋凉风飒然漫述","f":"五言律诗","c":["衡荜萧然迥，乾坤秋水中。","鸣蝉争落日，嘉树集清风。","即事从幽讨，因心合大同。","小山云露白，好植桂花丛。"]},{"t":"七月六日雨三章 其一","f":"七言律诗","c":["丰隆鞭龙龙疾走，惊风划裂土囊口。","黑云如磐压户牖，一夕四山万牛吼。","疏灯荧荧坐相守，娇儿宛转不离母。","西成禾黍复及期，于嗟苍天将尔为。"]},{"t":"七月六日雨三章 其二","f":"七言律诗","c":["窗穿片白天欲旦，开门邻比相呼唤。","檐攲屋漏各零乱，颓墙却壅人径断。","破衾斗粟夜来换，柴薪沾湿何由爨。","群儿长竿向水汀，戏拈蛛网捎蜻蜓。"]},{"t":"七月六日雨三章 其三","f":"七言律诗","c":["大河折南洲转北，突兀庄前走巨石。","合抱之树竟安掷，四松拔根良可惜。","栖苴瘣木争狼籍，陵谷由来轻变革。","县南村落得几户，明日城中卖老牯。"]},{"t":"萤火","f":"五言律诗","c":["小智吾怜汝，通幽解避明。","尚多清夜影，却受世间名。","一水湛天白，疏星绝汉行。","莎鸡兼促织，相与寄微生。"]},{"t":"十二乐秋辞 其一","f":"七言古诗","c":["廌青山中秋雨足，秋风萧萧被林麓，先登早秫次登谷。","老农涤场颜色喜，饱饭今冬到妻子。"]},{"t":"十二乐秋辞 其二","f":"七言古诗","c":["园桃累累枣垂垂，长竿踯躅跳群儿，窍凿未尽时天机。","石床阴阴枕古树，簪花梦作儿时舞。"]},{"t":"十二乐秋辞 其三","f":"七言古诗","c":["豆花蒙密薤叶肥，康瓠竟上邻家篱，小园抱瓮能灌畦。","庾郎清贫复何屈，每食盘飧二十七。"]},{"t":"十二乐秋辞 其四","f":"七言古诗","c":["鹿皮之翁拥肿馀，牧牛精舍方邻虚，香炉茗盌同安舒。","刳心楞严契妙理，不离一切根尘是。"]},{"t":"十二乐秋辞 其五","f":"七言古诗","c":["山僧在山便山处，絺衣粗疏杖手拄，云心无著鹤貌古。","偶尔相过啜新茗，指看月倒秋潭影。"]},{"t":"十二乐秋辞 其六","f":"七言古诗","c":["奚肩壶卢客戴笠，蹇驴轻快风习习，云卷波流迹谁蹑。","青溪蒙茸石崭岩，北山之北南山南。"]},{"t":"十二乐秋辞 其七","f":"七言古诗","c":["风廊稚女工拥彗，阿母桑户勤补缀，淫心舍力知相戒。","一灯入夜话秋雨，灯底阴虫亦尔汝。"]},{"t":"十二乐秋辞 其八","f":"七言古诗","c":["日来竭蹶官粮完，里胥不到鸡豚安，大男小女同欢言。","西邻饷黍东馈瓜，迭为宾主如一家。"]},{"t":"十二乐秋辞 其九","f":"七言古诗","c":["溪南偶逢桑苧翁，白堕酌予尊且空，盘礴白石荫长松。","卢胡一笑人不会，岂必齐谐裁志怪。"]},{"t":"十二乐秋辞 其十","f":"七言古诗","c":["村樵入云不见云，芒鞋齧入青苔痕，小髻插花肩负薪。","戒子勿深深有虎，叉手告予有老母。"]},{"t":"十二乐秋辞 其十一","f":"七言古诗","c":["荒陂无人秋草逼，轻霞反射西树黑，牧唱风吹下岩侧。","村女如识柴门路，群鸡飞上山樗树。"]},{"t":"十二乐秋辞 其十二","f":"七言古诗","c":["石坳甾嶷数椽屋，麇麚宿场鼪缘木，天如相予玉反璞。","隐侯之拜非吾徒，游鱼泼泼忘江湖。"]},{"t":"溪上","f":"五言律诗","c":["客心窅然注，秋水恰相关。","取适忘趋舍，无人自往还。","岁时芳草暮，江海白鸥閒。","独有高天月，相期在一湾。"]},{"t":"独游石塘峪","f":"五言律诗","c":["每爱盘空曲，白云深复深。","谁为高士传，不识古人心。","绝迹许长往，好山唯独寻。","一瓢毋我慁，天籁在风林。"]},{"t":"小园口号","f":"五言律诗","c":["静理入閒趣，方知天地功。","栗皱开夜雨，豆荚喜秋风。","不死身从老，安贫养已丰。","平生狷介志，汨没寂寥中。"]},{"t":"赠医者","f":"七言律诗","c":["几载悬壶汝南韨，伊人玩世而济世。","笑口何妨数解颐，仁心不恤九折臂。","丈夫相赏自有真，白鸥黄鹄谁能驯。","长镵斸破寒云色，予亦南山采药人。"]},{"t":"雪夜同藏上人宿云公房","f":"五言古诗","c":["车马各有归，累累独焉寄。","重阴逼短景，庄馗凛寒吹。","纡步造荒寂，稍稍林鸟萃。","兰若不受喧，琉璃瑩昏翳。","云公白业者，慧珠方内閟。","握手各欢然，龛灯照心契。","诗写秋冰清，雪杂软语细。","严警谢远柝，孤僧宣夜呗。","境远浮沤轻，理足弊屣赘。","止托良自已，于焉增叹喟。"]},{"t":"寒夜石东村留宿东村村舍","f":"七言律诗","c":["孤鸿翅垂老蛟蛰，暮天苍莽惊飙急。","时辈相逢龃龉多，南辕北辙宁相及。","促膝东村村夜长，爱客偏论上下床。","感君意气为君舞，喔喔鸡啼木末霜。"]},{"t":"有怀藏公","f":"五言律诗","c":["本色行真意，吾师得自然。","了无一物在，不异众人前。","世路老犹梗，心灯默已传。","客魂常自怪，动落法云边。"]},{"t":"山居杂咏五首 其一","f":"五言律诗","c":["双坞人烟外，萧萧松雪翻。","老农今日事，古色数家村。","鹅鸭通前浦，豺狼到小园。","何须不来往，邻里数相存。"]},{"t":"山居杂咏五首 其二","f":"五言律诗","c":["半尺青溪水，沧浪或在兹。","草香回蛱蝶，沙迥宿鸬鹚。","白发悔他日，清流信此时。","虚舟吾意得，飘荡更何之。"]},{"t":"山居杂咏五首 其三","f":"五言律诗","c":["一雨柴门路，纷然掩碧莎。","澹怀随老至，小隐畏人多。","泽雉安微分，醯鸡有太和。","寄声旧朋好，莫复笑蹉跎。"]},{"t":"山居杂咏五首 其四","f":"五言律诗","c":["峣崅南山口，参差晚稼陈。","谁知荷锄者，不是带经人。","天地容归老，妻孥恕食贫。","秋风看近在，红稻一尝新。"]},{"t":"山居杂咏五首 其五","f":"五言律诗","c":["耳目都无事，空山贡寂寥。","飞生时探鷇，稚子日承蜩。","苍莽情焉薄，胚浑器不雕。","初非事高尚，于以永今朝。"]},{"t":"晴晴","f":"五言律诗","c":["閒色开金碧，空山受夕晖。","秋心先候得，天意放晴微。","老去馀霜鬓，归来此亦衣。","暮途规海运，谁见一鹏飞。"]},{"t":"晚看秋山红树","f":"五言律诗","c":["谁擘珊瑚树，枝枝出海云。","炉锤真宰在，图画鬼工分。","白水开虚照，青山设閒文。","所悲摇落近，倚杖及斜曛。"]},{"t":"雨后病起赴邻家饮","f":"五言律诗","c":["霜树争开锦，秋沙不惹泥。","病翻嫌伏枕，晴即乐扶藜。","理得形原赘，机忘物已齐。","邻家邀痛饮，醉影恣东西。"]},{"t":"汎舟东郭观打鱼晚直雨","f":"古风","c":["蒙气变萧晨，秋坰森万象。","舍策理扁舟，容与淳?瀁。","肃杀顺金侯，佃鱼快心赏。","鳣鲔连兹乌，次第丽予网。","初焉乱蘋藻，歘吸凌菰蒋。","犗饵何足投，蛟龙群震荡。","竭泽义所妨，忘筌理宁爽。","凝阴盛亭午，寒雨洒莽苍。","生烟覆縠波，中流戛兰桨。","涵虚纳澄照，抱寂应空响。","卓彼赤水游，眷焉怀象罔。"]},{"t":"十月二十有八日夜集石东村咫尺斋因赠方士启陈卫瞻二子二十二韵","f":"五言古诗","c":["隙地乾坤迥，微阳草木衰。","猥承朱履倒，旋报白驹维。","东郭襟欢接，茭亭食允宜。","一枝巢并寄，十笏榻分移。","酒熟词靡隐，灯昏坐入危。","神龙吟下泽，鬼物瞰空墀。","汶汶□尘辟，京京宿卢堕。","侧同君子席，乐观主人仪。","有美称联璧，孤标准一葵。","奔趋瞠且后，羁旅傲难羁。","缥帙深紬绎，青囊妙指撝。","极臻穷奥窔，宏槛抉藩篱。","毛薛谁方驾，班扬固等夷。","德全身在野，识密字搜奇。","达士能通俗，高怀转即卑。","曲针惭见受，方枘嘅安施。","广废丛呵叱，郦狂易诋欺。","世情嗤古处，天意试长饥。","计拙蒙徒击，年侵节苦持。","风尘馀独立，肝胆积无私。","故旧嗟何托，平生重所知。","千秋唯此夕，吾道实凭兹。"]},{"t":"雪夜读赛岸亭溯源堂集率题其后","f":"古风","c":["刘青枝，钟酂湖，卓荦傲岸相枝梧。","清词奥语与世殊，白日鞭挞神灵驱。","先后相逢京雒道，交口誇余岸亭好。","微官罢斥役不除，贫骨支离学深造。","几回物色驱羸马，风尘一面天难假。","鼠肝虫臂奄忽陈，神都气索沦风雅。","寒灯夜雪天寂寥，残编在簏光怪摇。","繁声促节心离骚，郁为变徵行金飙。","铦刀解牛肯綮中，古霤滴石觚棱凹。","千秋此道许神遇，谁谓一日无知交。","呜呼隐微感倡随所遭，鸴鸠威凤同啁嘐。"]},{"t":"留宿陈卫瞻易安书室口占以赠 其一","f":"五言律诗","c":["甲第峥嵘在，蜗庐膝易安。","夜霜神骥立，秋水白鸥寒。","蓟训争相接，韩康窃自完。","过从能不厌，移榻罄清欢。"]},{"t":"留宿陈卫瞻易安书室口占以赠 其二","f":"五言律诗","c":["灯影深帘閟，炉香裛细匀。","玄言时一中，交道莫轻论。","琐事侵残岁，芳筵醉野人。","凤雏君已得，便足慰清贫。"]},{"t":"涉雪行","f":"七言古诗","c":["春城晓雪何霏霏，朝官玉珂声不迟。","二三君子拥衾卧，天其或与吾侪私。","陈遵好客好不已，割鲜切鲙重逶迤。","仆夫从容理短策，我马既秣牵载脂。","野心狸与清旷接，谢此城韨还郊圻。","翩翩公子携佳儿，石麟风度尤岐嶷。","襜褕殷红白马白，五陵谁敢誇轻肥。","朱君閒雅鹤氅披，仓头肩耸清琴随。","浏浏天风洒松雪，好事往已传雷威。","中有古德殊清羸，萧萧独鹤藏山师。","空机远趣日领接，路滑无若苍天为。","锴也拥肿真狂痴，鹖冠伏轼常鸡栖。","无终高躅岂终继，野谷实与愚公宜。","酒徒任达材不羁，动止不与常人齐。","行歌参差向幽仄，寒雀饥绕车轮飞。","孤村小落绝人迹，浅塘枯柳横天机。","此时六合入太素，空明一片青玻瓈。","如此不乐将安归，老去相逢能几回。"]},{"t":"雪夜听抱光弹涂山古操","f":"七言律诗","c":["玉轸高縆冰蚕丝，成连能事君庶几。","神明内肃气息微，灯青雪白情远移。","渊渊勤德古响稽，玄圭绣服灵依稀。","龙蛇蛰伏江汉回，侧身南望长嗟咨。"]},{"t":"破箑叹","f":"五言古诗","c":["破箑制自谁，阙略亏半月。","君恩讵不怀，想见凉风发。","微音谢衣里，判然隔胡越。","上有相思字，痕深字不灭。","已矣长弃捐，秋水沅湘阔。"]},{"t":"雨后西轩夜酌","f":"五言律诗","c":["雨意报阑珊，归云几片残。","月清今夕景，天复暮春寒。","虚闻增深悔，衰情灭宿欢。","浊醪曾不饮，一涉醉乡宽。"]},{"t":"咏山堂牡丹","f":"五言古诗","c":["宝栏倦矜春，素景回青芜。","金缕错纤葇，水碧承轻拊。","玉立初亭亭，□态纷自如。","縠云曳春江，窅渺一何疏。","湘灵尚皖洁，洛女流丰腴。","庄色洗妖淫，芳香烂吹嘘。","流光既云暮，孤趣宁自殊。","沃若桃李花，先春遂荣敷。"]},{"t":"黔石图歌","f":"古风","c":["雷霆划然轰鬼蜮，明珠翠羽纷狼藉。","轻车薏苡莫相乱，归帆唯载黔阳石。","石腹谺张颠盖攲，灵窦纡回通络脉。","屹立三尺具孤介，神韵古穆骨羸瘠。","儿时摩挲弄寒碧，老大爬罗还抉剔。","可怜兴替凡几回，五十年中事历历。","比邻冷君东海秀，挥洒天风动潮汐。","林离纸上如有声，走笔为我旋貌得。","浓阴沈黛召秋气，汇为风雨天深墨。","是时主客意震竦，竖尘微笑藏公貊。","呜呼庭前几上双拱璧，幸不相离常宝惜，平泉醒酒非所识。"]},{"t":"暮春陈橘洲过五石瓠堂会若水上人至清华激射喜而有赠时予将偕若公入田盘而橘洲有志未果云","f":"五言古诗","c":["束发重交游，落落悲素守。","荒涂矩跬步，局蹙惊蓬走。","天风吹所知，粲然罗户牖。","所知问为谁，二三同心友。","矫矫太丘裔，风华擅琼玖。","清畅发高言，岱华眇培塿。","若师汉川逸，止水崇虚受。","如意获宝珠，陀罗悟金手。","空机时晏陈，实理恣缓扣。","嚣尘庶荡涤，柴栅一击掊。","杖策随支公，明发就南亩。","离合无常期，春云独回首。"]},{"t":"秋初过陈橘洲有作","f":"五言律诗","c":["秋水连沙雨，衡门且暂临。","愁兼芳草暮，迹混白鸥深。","交道看前辈，文章见古心。","尹班投契旧，不厌屡招寻。"]},{"t":"溥元五侄寄藤杖却寄","f":"五言律诗","c":["正欲秋山去，苍藤寄此时。","老夫何所赖，一物见深知。","野步踰规矩，閒心混险夷。","清秋天地肃，寒翠入支颐。"]},{"t":"山楼对雨却寄京国诸同人","f":"七言律诗","c":["古情脉脉终何极，老鬓萧萧不耐秋。","八月关河横暮色，四山风雨入危楼。","残书过眼愁深解，荒稼侵寒任晚收。","好我故人休系念，知吾身世付虚舟。"]},{"t":"登楼","f":"五言律诗","c":["落日登楼意，沧州万里遥。","云阴冥屈蠖，风势侧盘雕。","俗物毋相乱，秋山肯见招。","寒芜横暝色，抱膝得无聊。"]},{"t":"独游","f":"五言律诗","c":["孤鹤寄天地，旷然江海心。","偶游碧云影，遂入青岚深。","所得憺已足，此身閒至今。","君听幽涧水，不作陇头音。"]},{"t":"石塘峪","f":"古风","c":["孤策狎清旷，萧晨纡远步。","坦怀足虚受，延接生妙悟。","复岭抱重冈，奇搆见回互。","石豁白云屯，岩张流水住。","人迹阒云灭，残村寄深处。","败垣立缺齿，老屋饱撑柱。","臼冷肥?穴，场荒射干赴。","山田久污莱，依稀辨樵路。","缅彼岩栖人，白骨委丘墓。","情专理岂敚，火传薪偶傅。","搴蓬启长叹，苍苍夕阳暮。"]},{"t":"八月十一日夜坐月","f":"五言律诗","c":["风壑消群籁，月明清露漙。","无言重捲幔，危坐一凭阑。","秋水乾坤白，冰壶草木寒。","百年疏鬓影，回首却愁看。"]},{"t":"课僮穫稻石塘冒雨归萝庄作","f":"七言古诗","c":["伧父磨镰清冷溪，深山晚稻收新菑。","主人携瓢奚负米，田家作苦劳佚齐。","白沙红树不辞远，山烟水气潜相资。","晦明呼吸生变态，岩雨淅沥吹凉飔。","泠泠空响泛清听，寒蛩暮雀咽不啼。","滑苔古磴有蹉跌，浅草仄坂无污泥。","短蓑轻笠便利见，拄杖亦足扶倾危。","少年江海累行役，汗漫今得平生奇。","归来妻孥笑沾湿，翻羹未足窥吾私。","石楼倚啸暝云合，山空木落孤鸿飞。"]},{"t":"搆屋石塘峪漫成五首 其一","f":"五言律诗","c":["更凿云林僻，端令世事遗。","古心栖沕穆，远迹擅幽奇。","高水循循落，空天浑浑垂。","一峰危立处，新结小茅茨。"]},{"t":"搆屋石塘峪漫成五首 其二","f":"五言律诗","c":["丛苞相倚薄，樵径曲裁通。","鹿叫寒岩雨，鹰翻绝壁风。","谩言青鸟使，或有紫芝翁。","头白沈冥意，吾将属此中。"]},{"t":"搆屋石塘峪漫成五首 其三","f":"五言律诗","c":["昔年空翠里，萧索几人居。","琐琐虫沙变，悠悠日月除。","石崩蹊又改，泉壅窟重疏。","记取田盘老，今为寄籍初。"]},{"t":"搆屋石塘峪漫成五首 其四","f":"五言律诗","c":["春水看龙变，秋风有鹤鸣。","虚怀依妙道，晚节慎平生。","坞仄从云卧，田荒费火耕。","凿坏犹赘事，自不系浮名。"]},{"t":"搆屋石塘峪漫成五首 其五","f":"五言律诗","c":["客屐经过处，应迷此一方。","阴崖缠雨气，午日动朝光。","山鬼来争席，溪禽不乱行。","夷歌君且听，髣髴古沧浪。"]},{"t":"雪","f":"七言律诗","c":["荒鸡不啼樵唱歇，开门千山万山雪。","空天追琢玉清澈，枯林古石寒轇轕。","屋茅颓唐脊半缺，山童绠汲井泉冽。","穿屦行吟客孤绝，黄鹄东来啄冰窟。"]},{"t":"七益诗 其一 那舍人慎脩","f":"五言古诗","c":["北陆极穷阴，微云晚凝冱。","昭然剥复际，青灯结良晤。","曰善匪外来，闻义由积著。","韫玉折方流，疏麻建直度。","孤节谅不移，雪霰亦已屡。","流议骇所遭，维皇眷深顾。","生植忧患丛，暄回闭藏固。","明两属休时，终焉令名树。"]},{"t":"七益诗 其二 吴纂修晚亭","f":"五言古诗","c":["黄鹄翩然飞，六翮自脩整。","秋风振广漠，江湖乐清迥。","龙仪格精妙，象纬穷彪炳。","自结耨野知，端殊扫门请。","金闺籍晚通，兰台笔新秉。","云蒸示鸿业，川竭昭深警。","下风邈焉承，裴回独引领。"]},{"t":"七益诗 其三 石国学东村","f":"五言古诗","c":["靡靡平乐习，华侈相崇高。","幽兰芳意别，神剑精芒韬。","风烟扫遗迹，筑馆邻近郊。","微吟弄篇翰，绠汲古兴遥。","方沼延素月，虚亭会凉飙。","佳期肯云旷，胜引时招邀。","授餐联日夕，絷驹竭场苗。","顾予悲触藩，趑趄良告劳。","废瑟奏深堂，节应宫角调。","将无叶公好，坐使尘清标。"]},{"t":"七益诗 其四 陈州佐橘洲兄弟","f":"五言古诗","c":["济济海城彦，夙著珣珉称。","渥洼贱孤骋，鸑鷟矜双鸣。","豁此尘外襟，蕴结初古情。","荒涂析蒙密，绝响寻铿鍧。","挥颖传三仓，抚几拥百城。","铦力无留割，乱丝何牵萦。","育兹千里材，继踵舆歌清。"]},{"t":"七益诗 其五 陈道人卫瞻","f":"五言古诗","c":["五石不可鍊，三芝复谁采。","每生惑未祛，徒劳望瀛海。","夫君秉道器，一致通恢恑。","斗室杂冲衢，泠然脱尘滓。","灵药匪外求，珠宫敷玉蕊。","松菌坚脆殊，颓颜侵壮齿。","天和能饮人，倾阳驻残晷。","奚必御飞龙，遥从羡门子。"]},{"t":"七益诗 其六 朱居士抱光","f":"五言古诗","c":["素质萃精纯，恳恳复款款。","楚璞谢追琢，湘筠办高简。","时髦而古趋，斯人希在眼。","岐路虽多岐，复之则不远。","一击傥不中，苍鹰瞥然返。","折节专事尚，三冬户云键。","咏歌先王风，弹琴助游衍。","宣尼如可作，深思寄狂狷。"]},{"t":"七益诗 其七 西涧开士藏山","f":"五言古诗","c":["明星何烂如，满月湛虚白。","根形木讷中，妙相不可测。","藕丝擢污泥，况在水精域。","溪云了变灭，松风叩空寂。","时闻迦陵音，鷇鸣一諠然。","二鄣方拄中，对之辄冰释。"]},{"t":"正月十有四日桐公至自普陀因同藏上人留宿萧斋分赋得分字","f":"五言律诗","c":["离立联双鹤，孤飞掣断云。","蓬茅忘简略，故旧接殷勤。","海色三衣见，兰香四座分。","踏灯歌歇未，明月照同群。"]},{"t":"得次女泸川信却寄三首 其一","f":"五言律诗","c":["远隔三年面，今朝万里书。","夜猿巴峡苦，秋雁合江疏。","作妇勤毋恤，思亲病可除。","天涯小侍女，相伴意何如。"]},{"t":"得次女泸川信却寄三首 其二","f":"五言律诗","c":["杜母讴歌处，儿今复滞留。","云深诸葛庙，花亚锦官楼。","文物移新俗，江山似昔游。","存亡两不见，悽恻泪长流。"]},{"t":"得次女泸川信却寄三首 其三","f":"五言律诗","c":["敢望生豚子，犹能隐鹿门。","轩墀邻虎豹，衣食仰乾坤。","白发穷愁豁，青山病骨存。","归帆如果发，先到薜萝村。"]},{"t":"夏日山居即事书怀三首 其一","f":"五言律诗","c":["村径通荒寂，悠哉此一隅。","晚凉移暑湿，空翠落虚无。","山意完深境，天然畀老夫。","君看黄雀思，自与白鸥殊。"]},{"t":"夏日山居即事书怀三首 其二","f":"五言律诗","c":["沙平时薙草，石冷重移苔。","野蝶忘人面，山禽覆茗杯。","地偏群动寂，偶丧百愁开。","云露高寒表，樗榆育不材。"]},{"t":"夏日山居即事书怀三首 其三","f":"五言律诗","c":["草木区萌遂，禽虫乳孳多。","独吟还自放，晚起且谁何。","邻里稀相接，樵苏也不过。","赘疣容圣世，敢复恨蹉跎。"]},{"t":"雨后观倒影潭","f":"五言律诗","c":["每爱空潭水，匉訇出郁盘。","喧流能入静，躁势转增寒。","未失和柔性，谁穷激怒端。","乾坤夷险事，云外侧身看。"]},{"t":"同藏上人避热倒影潭","f":"古风","c":["青天岂或生十乌，蕴隆欲逼林峦枯。","畏暑何处暑可逋，澄潭壁罅开冰壶。","白云翻空碧沙湛，表里洞澈颇黎铺。","新苔落花工绮错，轻鯈小鲒符中孚。","老僧磅礴露顶颅，赤脚大叫醒狂奴。","双厓散迸鲛人珠，金膏水碧何所须。","铁网摆落红珊瑚，深喜此地炎蒸无。","不唯炎蒸无，乐饥亦足终吾徒。"]},{"t":"和答陈石闾三首 其一","f":"五言律诗","c":["苍莽秋风落，凄其楚客悲。","卜居多龃龉，寄食有胥靡。","朱瑟蒙尘网，清冰瑩藕丝。","龙蛇君不见，吾道属逶迤。"]},{"t":"和答陈石闾三首 其二","f":"五言律诗","c":["閒馆莓苔合，经今限短垣。","雄鸡蕲断尾，芳草怨当门。","萋斐知何意，颠危见所存。","明时天广大，无事泣烦冤。"]},{"t":"和答陈石闾三首 其三","f":"五言律诗","c":["风雅黄初后，谁知此道难。","时趋尝折角，绝诣早登坛。","同□惭深予，新诗忍细看。","文章疑鬼物，容易致泥蟠。"]},{"t":"平谷县南楼晚眺","f":"七言律诗","c":["垂老临高可若何，百年强半付蹉跎。","寒云直接卢龙塞，古水裁存独乐河。","晚色关山疲马在，清秋天地断鸿多。","孤城寥落烟霜冷，扶杖南楼一暂过。"]},{"t":"杪秋杂感 其一","f":"五言律诗","c":["平居抚今昔，幽感恻心魂。","遗泽弥梁楚，清操著子孙。","园庐聊僦止，饘粥强图存。","三十年中事，凄凉莫重论。"]},{"t":"杪秋杂感 其二","f":"五言律诗","c":["每作西南望，沾襟涕泗斑。","秋心悬博水，风木拱尧山。","谁策遗经美，空存赐服殷。","传□旧祠庙，犹祀峡云间。"]},{"t":"杪秋杂感 其三","f":"五言律诗","c":["才拙官宜罢，家贫子亦无。","生涯违左计，迂步狎泥涂。","落落馀今日，悠悠此丈夫。","愁边霜叶脱，独立一长吁。"]},{"t":"杀虎行","f":"古风","c":["握折刀，挥缺斧，山伧三五能杀虎。","爪牙犀利皮斑斓，乳虎之怒良可干。","南山日夕羊牛下，牧笛孤吹行路难。"]},{"t":"初秋晚坐新亭咏怀","f":"五言古诗","c":["众草抽柔心，高云变新色。","静惟所凭功，敷展殊莫测。","素商易朱明，金气先驱亟。","萧萧丛莽振，翏翏虚谷涤。","大化宁异权，盛理欲谁抑。","通蔽无易力，迷顺有失得。","席荫空亭阴，予景庶终息。"]},{"t":"赠东竺极上人","f":"七言古诗","c":["廌峰古翠何絪缊，惟与东竺为比邻。","群松龙立石虎蹲，厥水甘冽壤黑坟。","庵摩罗果宜时珍，秋实万颗玛瑙匀。","上人高悟忘我人，勇猛之性坚刚身。","一毛刹见虚空新，琉璃映彻净妙陈。","宝丝网缀何纷纭，精蓝岁时供米薪。","腰包肩担接众勤，法用平等齐富贫。","世如师者今罕闻，神珠在衣宁卒泯，忍草三嗅馀幽芬。"]},{"t":"秋日同藏师若师息亭雅集分赋","f":"七言古诗","c":["蓬累恣孤行法幢，许双建世我宁殊。","涂邂逅尘坌远道，协背膺合吐纳符。","一券丘琴弄清响，茗柯味馀善穆穆。","山横秋肃肃风吹，万嘉游匪素期遁。","迹果初愿息心欢，有徒终焉得无闷。"]},{"t":"倒影潭听藏公弹琴因怀抱光子","f":"五言律诗","c":["天籁溢青冥，风潭洒翠屏。","谁知七弦上，空响亦泠泠。","金石应诸节，蒿蓬振百灵。","平生耽古调，惟向二君听。"]},{"t":"蓟门怀古五首 其一 碣石","f":"七言律诗","c":["长淮直接大河冲，无数堤防日夜供。","瓠子几劳沈璧马，烝黎时复喂蛇龙。","九河震荡沦初迹，四载胼胝忆旧庸。","日落海门还倚杖，每从碣石认尧封。"]},{"t":"蓟门怀古五首 其二 孤竹","f":"七言律诗","c":["亦知天眷已西临，独信民彝待力任。","叩马责难君父义，采薇之死弟兄心。","漆书旧简清风在，草蔓荒祠古色深。","历历遗歌著仁暴，不胜凄绝一长吟。"]},{"t":"蓟门怀古五首 其三 渔阳","f":"七言律诗","c":["渔阳古郡接边陲，张郭循良旧所推。","再见炎灵开草昧，顿令编户起疮痍。","桑麻夜雨新畬辟，鼓角秋风故垒夷。","何地岩疆称重寄，从来民命系安危。"]},{"t":"蓟门怀古五首 其四 北平","f":"七言律诗","c":["故李将军猿臂奇，能堕纪律老行师。","数临沙漠终无当，一踬泥涂亦可悲。","避舍碛中传姓氏，封侯戏下后偏裨。","北平此日秋风落，更有飘零哭数奇。"]},{"t":"蓟门怀古五首 其五 卢龙","f":"七言律诗","c":["无终山翠镇萦纡，乱世真宜聚族居。","深喜渔樵时往复，不知宗社日沦胥。","戎车自足通荒塞，束帛何烦及弊庐。","尚有野人寻隐迹，石梁云壑莽成墟。"]},{"t":"秋日谒轩皇庙","f":"五言古诗","c":["土德承炎统，雷光兆斗枢。","帝鸿开宝历，少典扩皇图。","荡涤乾坤色，昭回日月模。","窟巢淳古辟，轨物嗣王趋。","圣实推先觉，天方剖众愚。","道隆九纪著，政洽八荒苏。","襄野曾纡驾，凶黎敢后诛。","应龙披毒雾，牧马喻迷涂。","俛仰寻姬水，传闻异鼎湖。","一丘纯质见，百尺此厓孤。","神鬼呵虚殿，山河拱旧都。","溯时绳契远，徵俗礼文敷。","画壁讹虫鸟，灵旗荡虎貙。","树声商或奏，云意白仍铺。","岁享劳耆叟，秋风拜匹夫。","载寻陶铸迹，妙绪启唐虞。"]},{"t":"寓居广化寺作","f":"七言律诗","c":["愁向飞蓬问故根，寒云乔木独伤魂。","夕阳自照乌衣巷，细路裁通祇树园。","入耳清钟时起灭，避人栖鸽尚飞翻。","骑驴谩作西州哭，零落于今不可言。"]},{"t":"移寓又作","f":"五言律诗","c":["病起身何托，天寒寓又移。","蛰虫振冬户，宿鸟落风枝。","赘物辜生德，畸人赖圣时。","寝丘遗产尽，谁念叔敖儿。"]},{"t":"留宿友人易安书屋","f":"五言律诗","c":["客自无归处，长安路不迷。","偶然留半榻，便已足羁栖。","说剑神尤王，论文鬼欲啼。","朔风吹败叶，无事日东西。"]},{"t":"刘东郊来自广陵喜赠","f":"五言律诗","c":["羁旅清江曲，优游大壑前。","五年如一瞬，斑鬓映华颠。","古剑潜蛟泣，新雏小凤翾。","六朝遗迹泯，又得子山传。"]},{"t":"虎子行赠石君东村","f":"古风","c":["君家虎子蔚豹文，短小精悍骄不驯。","问年裁及龆毁新，方颐阔颡骨肉匀。","电光疾闪双瞳神，轻貂插帽玉琢带。","窄靿靴跐天街尘，番刀快割不肯离。","璁珩觿韘徒横陈，北山之石维四钧。","兀然高广半及身，有时斜睨一笑申。","双拳龙攫胯虎蹲，宝鼎足举山拔根。","观者咋舌宾客笑，群儿慑伏咸逡巡。","君不见朱丝脩长断复续，系颈累累古相属。","天生此儿必有为，姑墨龟兹其蚤服。"]},{"t":"立春后一日集饮范兰亭佛籁轩","f":"五言律诗","c":["卓立维公子，招邀及老夫。","春风善披拂，衰草不荒芜。","一邑围烟水，高斋入画图。","醉深灵籁起，略扫客尘无。"]},{"t":"妖梦行哭东郊刘子","f":"古风","c":["青滋山人汉王孙，产古楚地今吴门。","秋心古貌凛然具，滟滪之水潇湘云。","雄才跨陵邺都客，自许卓荦能偏人。","少年客游老不返，负笈历遍天涯春。","江涛海色揽欲尽，裋褐饱掬京华尘。","低佪赵魏区，流览咸阳道。","探索邯郸战伐危，荡磨太华阴阳老。","凤台牛首烟雨秋，归去更作金陵游。","酒酣放笔真宰赴，国殇山鬼啼阴幽。","君年六十举一子，三载盈盈限秋水。","故乡不归归异乡，人生有情宁乐此。","秋山友人遗尺书，报君白首来京都。","玄州十月一把臂，惆怅垂老犹饥驱。","短日迫虞渊，不得驻斯须。","清冰寒迸玉壶碎，霹雳骇震丘琴枯。","忆与君订交，乃在庚子冬。","惊飙振霜原，安能定飞蓬。","中间离合经一纪，壮齿亦复成衰翁。","昨夜昏灯入妖梦，先期死友精诚动。","素车白马城东来，失声一拍成悲恸。","天青月冻风凄凄，严霜古瓦鸺鹠啼。","孤魂荧荧夕几逝，江云燕树增迷离。","老妻向衰暮，娇儿方孩提，可怜茕独谁依栖。","新诗简练齐杜陵，壬子况复同年生。","君当休明彼昏乱，生死遭遇何同情。","皇天独畀身后名，呜呼皇天独畀身后名。"]},{"t":"拟古乐府五首同石闾作 其一 短歌行","f":"五言古诗","c":["野蒿上参天，荼荠称圣贤。","枯桑何萧萧，飘风不崇朝。","世短裁瞬息，夜长愁莫极。","生年或欲引，药石不可准。","缀石丝且断，蕴热鱼自烂。","黄雀鸣复飞，毋为人所哀。"]},{"t":"拟古乐府五首同石闾作 其二 思公子","f":"古风","c":["枯蘖求新苔，斥卤望芳草。","东风过残春，脉脉伤怀抱。","策我假，牵我脂，飞龙蜿蜿黄金旗。","梦中识路觉后疑，孤云遥裔天一涯。","我梦梦君君不知，黄姑织女长相思。"]},{"t":"拟古乐府五首同石闾作 其三 边笳曲","f":"古风","c":["胡霜作苦风作酸，黄芦卷叶吹夜阑。","牙旗萧萧堠火死，万马回首云中看。","寄语瓯脱儿，边笳且莫吹。","朝来鏖战皋兰北，入耳军心有别离。"]},{"t":"拟古乐府五首同石闾作 其四 燕歌行","f":"七言古诗","c":["韨中年少轻去留，爱骑白马锦傅韝。","鸣珂朝驱平乐观，趿履夜上倡家楼。","买醉徵歌取快意，按板不正红裙愁。","平生豪侠一二数，腰间敢佩双吴钩。","丈夫沈滞不若死，年过三十羞封侯。","抱关屠狗何为者，笑汝悠悠蚤白头。"]},{"t":"拟古乐府五首同石闾作 其五 雉子斑","f":"古风","c":["麦垄閒閒雉子斑，饮溪啄薮时翩翻。","南风悠然百灵化，冥冥至道曾无前。","穿牛络马小智作，涅乌浴鹄伤其天。","工倕易伎殊巧废，离娄改听庸人先。","物性有固然，君不见雉子斑。"]},{"t":"饥齧槽","f":"古风","c":["饥齧槽，槽剥齿，骨肉中乾毛色毁。","强神独立或不死，一鸣何伤乃若此。","饥齧槽，风萧萧。"]},{"t":"秋笛","f":"五言律诗","c":["横笛秋风襄，可怜边思多。","一声折杨柳，残月下关河。","朔气潜相入，清商久不和。","方传郑都护，万里枕雕戈。"]},{"t":"出师","f":"五言古诗","c":["赤羽飞军阃，黄云绕祃坛。","出师罴虎奋，驻足士民看。","神策柔疏勒，天兵洗贺兰。","雪消龙马跃，鼠急豹旗寒。","报国须如此，封侯竟不难。","丈夫无涕泪，君子挟心肝。","颇牧筹真熟，甘陈事有端。","会传西域靖，喜见北门安。","日月原相照，雷霆莫可干。","防风毋后至，万一圣恩宽。"]},{"t":"江东慎行师拟止石堂因署曰梅子坞且赠以诗时又五月十有四日","f":"五言律诗","c":["流水忽欲住，湛然寒碧陈。","半椽聊托足，一笠不随身。","梅子熟何日，香光定染人。","会须同牧女，长共乳糜新。"]},{"t":"雨中口号","f":"七言律诗","c":["沙鸟容与易急湍，江鱼泼剌避渔竿。","百年野兴閒中得，一片浮云醉后看。","力役樵苏循草泽，高秋风雨入烟峦。","此身放浪无拘束，身外须知事事阑。"]},{"t":"喜范兰亭至","f":"古风","c":["六月荒林乳燕飞，相看相伴两忘机。","孤琴别鹤馀音远，秋水芙蓉往思违。","云壑久?埋马骨，巾车何意驻柴扉。","情深为贳前村酒，转醉空山老布衣。"]},{"t":"汉隶十帖歌寄陈不其","f":"七言古诗","c":["学书所贵探原始，熟精汉隶不其氏。","握虚浑噩真气行，折波收缩中锋是。","当时篆籀循古文，后来变隶变八分。","毁繁就约势莫遏，政如天运承冬春。","秦吏程邈创此格，中郎能事称绝伦。","臣有古癖期临摹，陈子不秘灵蛇珠。","史晨后碑首相赠，风骨古雅启坦涂。","继购八帖皆古拓，奏铭回翔殊合法。","杂华镂采纷馺还，百石卒史尤孤超。","云幢海若凌朝潮，百灵齐肃衣冠朝。","字裁盈寸曰孔彪，遒媚秀整初不媮。","惟三礼器出瘦硬，左飞右飞点画正。","倒悬石笋横流穿，屹立髯松山雪盛。","最遭剥蚀闻礼碑，朴拙钟鼎仪型垂。","孔宙碑阴亦有致，正碑余复新罗至。","雄强体势二寸弱，圆兼乙瑛瘦礼器，神鸾高鶱龙马驶。","宝玉五瑴呵神灵，怪底敝簏光怪生，对之老骨秋峥嵘。","纸残笔秃池水墨，累月学之犹不成，让子千秋绝艺名。"]},{"t":"灭蜂行戏作","f":"七言古诗","c":["轮囷老树空其中，裁有罅隙巢山蜂。","白蛇当道虎伏路，微物布势将无同。","纤尾怀毒等虿蝎，细腰蛊媚逾蠮螉。","经营采掇数十百，日夕飞集声匈匈。","入怀壮士闻色变，出衷孝子悲冤蒙。","么魔罪大莫可逭，扶义敢止儿童攻。","前驱贾勇后作气，不辞辛螫披群凶。","咸阳可怜一炬尽，函谷竟藉丸泥封，丑徒殄灭閒园空。","绿阴亭亭老翁喜，寒蝉细蝶秋风起。"]},{"t":"留宿梅子坞","f":"五言律诗","c":["云坞秋灯白，山深夜复深。","虚空开梦境，消息见天心。","零露攘攘下，阴虫细细吟。","百愁诚底物，悔被一生侵。"]},{"t":"射雉行","f":"七言古诗","c":["敦弓髇矢钧重轻，猎生石塘初酒醒。","一双锦雉向我鸣，子毋射予予肉腥。","胡不射虎古北平，快马脑后秋风生，垒落亦足豪其名。"]},{"t":"与藏师野步遂之东岭采蕨不得","f":"五言古诗","c":["归雁度欲尽，芳草萋以合。","行歌谷风徐，于喁互相答。","祛俗匪自力，清旷承延接。","远迹晦箕颍，馀情缀苕霅。","幽讨无定趋，天倪寄双屧。","循兹东峰阴，蕨薇或可拾。","彼茁想挛拳，非时敢淩躐。","眷言怀物理，繄谁利便捷。"]},{"t":"藏师饷予山豆苗诗以纪之","f":"五言律诗","c":["物美天难夺，飒然风味殊。","早春时采摘，小品擅庖厨。","滑腻江莼劣，甘寒玉笋俱。","豆苗谁种女，亦足养清癯。"]},{"t":"过山寺听僧说金刚经义","f":"五言律诗","c":["云迥双林近，沙寒细路移。","蛟龙秋竞起，虫豸晚犹啼。","一语清尘却，经时落日低。","是心何所住，流水自东西。"]},{"t":"城南行赠金雨山","f":"七言古诗","c":["城南委巷轮蹄希，中有一客来幽栖。","苍鹰翅垂罢淩厉，天马骨立犹权奇。","阴阳象纬理玄妙，七载胥靡撮其要。","泥涂英雄沦落际，犹足因人说忠孝。","媻姗蹩躠双足折，洪炉百鍊昆吾铁。","抱道敢信王骀尊，用知非关鲍牵拙。","冬寒今日无天风，杲杲日出扶桑东。","老夫贸贸久颠踬，邂逅凭君一击蒙。"]},{"t":"送范子弃宅入山","f":"七言古诗","c":["范君仙骨何珊珊，一日飞遁红螺山。","千金敝屣脱故宅，塔景虚闭清溪弯。","红螺山深隈隩窅，有田三顷茅三閒。","荒林野水伫客屐，高鸟亦破层云还。","谷神蕴中玄解入，万有空洞冥其天。","群羊鞭叱白石起，双龙豢食银涛翻。","云璈内回翠盖接，隔世一片唯虚烟。","廌翁憔悴栖廌峰，廌峰苍翠当其东。","何当食我青精饭，碧海青天一掌中。"]},{"t":"寄答慎上人 其一","f":"五言律诗","c":["万态争纷糅，孤云自溯洄。","不言看逝鸟，无赖画寒灰。","老骨支离耸，春星寂寞回。","萧斋愁正剧，珍重尺书来。"]},{"t":"寄答慎上人 其二","f":"五言律诗","c":["水石萧然外，孤茅亚雪深。","物方随荡涤，我亦乐销沈。","羁绁未终谢，梦魂时一寻。","坐看梅子意，已了即非心。"]},{"t":"鄂尔浑","f":"七言律诗","c":["壬子六月龙中昏，羌兵东下鄂尔浑。","王师角前戎掎后，血战一夕歼游魂。","牙旗累搴炮数夺，寒飙吹腥河水蔑。","碛中参伐动秋芒，妖狐夜舐骷髅血。"]},{"t":"癸丑元日柬藏公兼报石范二君消息","f":"五言古诗","c":["水石常流峙，观空趣日新。","年谁司去住，节谩别冬春。","寓道宁离相，依方早绝因。","丘林齐众妙，天地适斯人。","独立浮香海，群生触幻尘。","范丹愁束缚，石德易艰辛。","风隼收双翮，云鸾孑一身。","熟图归小隐，百计度清贫。","更切卑栖在，深惭困踬频。","泥涂长紊紊，牛马共甡甡。","袁虎仍舟子，王尼实隶臣。","知非衰齿近，寡过昔贤纯。","晚节敦初服，秋山立紫旻。","乱行缘自饰，息景转多嗔。","桃梗漂无极，衣珠照有神。","何当回般若，同与慧灯邻。"]},{"t":"差喜","f":"七言律诗","c":["差喜茅斋匝翠微，阒然常是阖双扉。","秋风中客吟芳草，老态催人看落晖。","云里桑麻终岁供，天边江海一渔归。","旧游三舍京华路，隔绝音尘万里稀。"]},{"t":"临水","f":"七言律诗","c":["几上残编倦不收，溪边沙鸟默相求。","看书忽下千秋泪，临水翻增万里愁。","老去襟怀偏忆远，古来辞赋已悲秋。","塾中同学今谁在，独许青山照白头。"]},{"t":"隐几","f":"七言律诗","c":["北舍南邻径自通，嗒言隐几鹿皮翁。","书看往事心冥悟，药及衰年病莫攻。","争席儿童忘客坐，过墙鸡犬报粮空。","逶迤世外无言说，聊集残编溯古风。"]},{"t":"石东村见寄以诗赋答","f":"七言律诗","c":["种瓜给日傍青门，门下曾谁感旧恩。","八口重兼诸弟在，十年今见一身存。","悲凉谩听雍门曲，任达还标犊鼻裈。","不乏故人同濩落，归来残叶下秋村。"]},{"t":"寄怀陈橘洲","f":"七言律诗","c":["横琴一弄雉朝飞，牧犊能忘雪涕挥。","委巷僦居容便得，閒园中酒醉方归。","友朋风雨谁频接，兄弟泥涂辱久依。","闻道深情注孤介，逢人尝话芰荷衣。"]},{"t":"秋望","f":"五言律诗","c":["赤日照沧洲，秋风吹白头。","尚怀千载虑，还向古人求。","老马不改步，野原今又秋。","楚天愁望断，脉脉下空楼。"]},{"t":"幽栖","f":"五言律诗","c":["沙碧长林曲，无人一径夷。","斗禽双堕地，交蔓各升篱。","心迹行都泯，文章老更疑。","子山他日赋，聊足述幽栖。"]},{"t":"石壁下看秋海棠作","f":"五言古诗","c":["晚色落蘼芜，霁晓扇商吹。","相羊款遐心，莽渺展清睼。","秋阳有不临，古壁丛苍翠。","阴精凝鲜葩，纚洒妖红被。","秾装沾露颊，翠羽褰风袂。","宓妃回灵旗，二姚亦爰戾。","遂生自敷畅，幽赏顾终惠。","意远如两孚，情深各为媚。","愿结青女萝，寸言傥可寄。"]},{"t":"长至前一日同人集睫巢草堂作","f":"五言古诗","c":["坚冰凝冻华，序届穷阴后。","严威蛰群动，朔风吹万有。","野老狎鸡栖，亲知等箕斗。","挈瓶胶故知，谁能易其守。","郊鸡期断尾，野马辞络口。","匠石徒有心，沟断终焉取。","诸君毓琳琅，相识各已久。","椒兰臭不移，欢焉此携手。","城边霜鸟下，天际孤云走。","乾坤回浩荡，兹会亦云偶。","吾生迫化迁，倏忽及衰朽。","昔为巢中雏，今作堂上叟。","浅抱迷达观，含悲泣刍狗。","北陆极寒曦，微荑震枯柳。","复姤理自然，私心重回首。"]},{"t":"赠华相野","f":"七言古诗","c":["画史精义妙入神，解衣盘礴当元君。","逡巡落笔后来事，冥浮物我几先申。","相城之野古宋墟，华生千载能相因。","水痕云叶动玩索，糟粕不受初古人。","冰缣藤纸张十尺，睥睨经旬如浪掷。","忽然中酒泼墨深，突兀高堂衡华逼。","百灵乍栖万有震，孤电远掣群阴辟。","有时设意不设色，歊云嫪雾飞空白。","技精阃奥古莫传，谁知用水胜用墨。","长安旅游游思孤，长揖却辞卿大夫。","肯跨青骡走荒僻，为我醉写盘阴图。","阴林日黑山鬼呼，灭景慎勿留须臾，与君斟酌为酒徒。"]},{"t":"八月接东村书闻遂移居盘阳以诗代柬赠答 其一","f":"五言律诗","c":["鹿车脂其牵，秋风吹我衣。","客子何仓皇，离居非前期。","骨肉惨不欢，牵袂邻儿啼。","虽殊千里别，转面长相思。"]},{"t":"八月接东村书闻遂移居盘阳以诗代柬赠答 其二","f":"五言律诗","c":["海鸟薄鲁羞，代马愁南辕。","佳城郁苍苍，况在青门边。","长跽却辞去，一日渝百年。","彼草犹青青，纡回墓门前。"]},{"t":"八月接东村书闻遂移居盘阳以诗代柬赠答 其三","f":"五言律诗","c":["蛇行不赖足，牛用不赖齿。","夫谁宰弘化，丰啬含妙理。","方舟溯大河，投竿钓王鲔。","落日射金沙，空波寒瀰瀰。"]},{"t":"八月接东村书闻遂移居盘阳以诗代柬赠答 其四","f":"五言律诗","c":["羁魂恋枯骨，雨夜翔幽林。","面交訾古处，今见君子心。","昨日故人死，今日故人去。","头白感伤多，人生甚流寓。"]},{"t":"八月接东村书闻遂移居盘阳以诗代柬赠答 其五","f":"五言律诗","c":["秋山抱孤村，葺茅枕虎落。","息肩匪恤劳，田家岁耕作。","大夫能纬萧，娇儿罔纺缴。","白马金当卢，看人返平乐。"]},{"t":"夜宿耳山山厦","f":"五言律诗","c":["只作吞声哭，真成隔世悲。","高坟徒再拜，旧业已全堕。","事著名臣传，惭深不肖儿。","耳山山厦月，相照欲何为。"]},{"t":"醉红亭秋望","f":"五言古诗","c":["日月惊心剧，乾坤放眼空。","塞寒霜欲度，山迥树新红。","虚壑委蛇出，生烟冥漠通。","境宽情自隘，愁绝理难攻。","往事浮云似，秋声落木中。","贵游销贱骨，白发变青童。","纵酒捐齐瑟，鸣髇废楚弓。","死生诸态见，哀乐几人同。","苦节偏求守，迷方固易穷。","虞卿原自窘，柳下讵为工。","独客凭荒槛，危亭战北风。","寝丘端在望，挥涕对飞蓬。"]},{"t":"村夜","f":"五言律诗","c":["路暝客行稀，林昏月上迟。","雨声黄叶下，阴火碧燐移。","寒事催荒徼，清砧急远闺。","和戎归圣算，近罢月氏师。"]},{"t":"野望","f":"五言律诗","c":["燕赵悲凉俗，唐虞揖让风。","古怀缘酒热，老眼得秋空。","易水销神剑，尧山泯故宫。","几多凭吊意，徙倚落晖中。"]},{"t":"呈晓亭少司农宗侯廿六韵","f":"五言古诗","c":["出震凭东极，含元建大中。","山河开蕴藉，日月荡洪濛。","龙变蒸云气，鹏飞碧海风。","轩邱鸣六相，沛下失群公。","矧以天潢近，巍然玉牒通。","分枝荣蒂萼，累叶奉昭融。","属者朝廷上，多君品节隆。","圣情舟楫待，农部版图充。","践履纷相委，操持切自攻。","赋班阡陌理，绩奏转输工。","骨性清超绝，文章造诣雄。","律谐钟荡涤，肉浑璧磨砻。","汲引贤无隐，登临险必穷。","远怀符胜具，深器挹虚衷。","忽枉青丝辔，猥存白发翁。","话言依厩底，物色到墙东。","兀兀荒江鹤，悠悠断渚鸿。","百年循墨守，一旦击包蒙。","进语询先德，当时亦总戎。","乘城被赤羽，辟敌有雕弓。","遂次皋夔末，能标尺寸功。","赏行劳顿著，报歉施弥丰。","俛仰惭衰影，栖迟笑薄躬。","主恩汪濊在，祖武缵承空。","故剑尘秋水，殊书积乱蓬。","不材如仆甚，何以谢帡幪。"]},{"t":"宿心上人房因赠 其一","f":"五言律诗","c":["枕藉长安道，栖禅十五春。","行深忘白业，门静辟缁尘。","摆脱随场惯，坚刚得性纯。","偶然分物我，一款故乡人。"]},{"t":"宿心上人房因赠 其二","f":"五言律诗","c":["射虎将军后，秋风弩蹶张。","如何明性觉，倏忽变行藏。","束缚悲余老，功能羡汝长。","玩花台不见，洒涕一凄凉。"]},{"t":"移居 其一","f":"五言律诗","c":["归老长安韨，鸡栖闭席门。","孤云无住相，衰草护春根。","里巷差能别，交游多不存。","空怜乱书在，似欲伴朝昏。"]},{"t":"移居 其二","f":"五言律诗","c":["西北严城角，何人问寂寥。","星霜乔木改，风雨弊庐遥。","春雁起湘渚，沙鸥去海潮。","故园为客意，伏枕得无聊。"]},{"t":"移居 其三","f":"五言律诗","c":["敢作无终隐，躬耕赡薄糜。","行藏真不料，五十复如斯。","啙窳吾生拙，崔隤老步迟。","请看南国橘，一徙一离披。"]},{"t":"韨上听人鼓瑟","f":"五言古诗","c":["初制庖羲启，悲情素女扬。","律谙孚上帝，风正协明堂。","疏越宜虚凿，朱丝喜縆张。","和平昌品物，精一洽阴阳。","悦耳新声变，经时古乐荒。","雨深寒宝匣，尘定积珠囊。","师旷曾无匹，匏巴独擅场。","破弦人孰敢，胶柱理真妨。","有客穷涂在，何缘此器将。","殷勤弹赵曲，索莫凑齐王。","兀兀幽燕底，栖栖韨井旁。","间能传髣髴，未易入清商。","大雅今谁作，元音岂遂亡。","洗心听再奏，吾意落三湘。"]},{"t":"新秋席上作","f":"五言律诗","c":["新凉上葛襟，萧瑟碧桐阴。","我固多愁者，君看草木心。","盛衰无再计，风雨为谁深。","高宴同杯酒，遥遥忆古今。"]},{"t":"秋风辞","f":"五言古诗","c":["眢井不可汲，乱丝不可治。","嫁女不嫁妇，非复少年时。","少年难再得，先鸣有鶗鳺。","平生不相识，胡为怨离别。","孤云本无根，芳草岂无节。","冉冉歧路閒，秋风为谁发。","秋风尔何心，吹我远梦断。","河水不通江，鲤鱼长尺半。"]},{"t":"送别若公南游 其一","f":"五言律诗","c":["扁舟下南渚，此意一何深。","自有真空在，谁从实际寻。","大江无定水，秋月照人心。","午夜鱼龙出，应听秘密音。"]},{"t":"送别若公南游 其二","f":"五言律诗","c":["松风扣虚壑，萧爽田盘秋。","每遇绝佳处，与师尝极游。","江湖今判袂，烟雨独登楼。","题遍南朝寺，无忘寄白头。"]},{"t":"寓西涧藏师竟赴千像寺斋孤游涧中竟日有作","f":"五言律诗","c":["滞理由拘士，遂令真意亡。","拂衣僧竟去，拄杖客何妨。","秋水飞空白，孤云无定方。","至人吾岂敢，耆旧在襄阳。"]},{"t":"展眺","f":"五言律诗","c":["临空展孤眺，山豁双眸开。","秋色无边际，高云万里来。","可怜牧马处，霜落单于台。","边吹切肌骨，至今生暮哀。"]},{"t":"散步石堂","f":"五言律诗","c":["自有茅庵在，因通石路微。","清溪十三曲，豺虎未云稀。","孤磬云际出，山霜八月飞。","爱兹多古意，白日澹空机。"]},{"t":"题射潮图","f":"七言古诗","c":["钱唐之水水波恶，百丈惊潮天上落。","太阴薄日群动栖，元气吹空万灵作。","治功伯禹称至神，会稽合瑞狂澜驯。","祖龙威力噬天下，上游慑气犹逡巡。","江东贾贩飞金镞，乃使江潮一朝伏。","河中有虎飞食人，关弓却射龙蛇族。"]},{"t":"寄怀若水上人 其一","f":"五言律诗","c":["江南秋草色，不染道人心。","片笠随终始，孤舟得滞淫。","乾坤幽梦破，风雨夜钟深。","万里冥鸿意，于今喜陆沈。"]},{"t":"寄怀若水上人 其二","f":"五言律诗","c":["不碍荒江曲，题诗杖竹筇。","乡心三户水，秋色六朝松。","梦幻能无著，虚空定所从。","沃洲山路塞，缘汝见孤踪。"]},{"t":"闻雁","f":"五言律诗","c":["边声不到地，哀雁塞门回。","老泪无端下，秋风薄莫来。","酒深时倚杖，人去独登台。","万里潇湘水，惊群几溯洄。"]},{"t":"秋草","f":"五言古诗","c":["萋萋复萋萋，秋草被长堤。","离披不盈寸，挽结长相思。","八月心不抽，九月叶不齐。","不惜芳翠歇，愿藉君马蹄。","马蹄去不返，风吹柳丝断。"]},{"t":"兔丝","f":"五言古诗","c":["纤纤兔丝草，袅袅引蔓长。","谁云无根株，可以缘众芳。","绸缪事冯藉，所缠成萎黄。","尝闻人有言，李树代桃僵。","美人步南园，采采归兰房。","缠我金步摇，绞切双凤皇。","随手寸寸断，私心冀有常。","江上生蘼芜，北风天陨霜。"]},{"t":"春风酒","f":"七言古诗","c":["中原游子老越乡，高楼女儿秋夜长。","饥则有糜渴有浆，安能使我离愁忘。","糟床注酒春风前，春风在酒不在天。","青尊一滴裁入口，春风在眉不在酒。","酒如铦刀愁乱丝，乱丝易斩愁难治，或有缠绵未断时。"]},{"t":"洞庭秋月行","f":"七言古诗","c":["沙棠之舟木兰楫，浅塘曲渚纷相入。","凉风拂水水欲波，洞庭无人愁奈何。","此时片月当人起，哀猿苦啼啼不止。","何处参差吹夜阑，相思移注繁声边。","金幢翠蕤骄不前，九疑滴滴空翠寒。","夜久风吹月西堕，欲堕不堕曲入破。"]},{"t":"射雉儿","f":"五言古诗","c":["射雉庚宗东，射雉庚宗西。","朝出不俟日，薄莫且未归。","贱子何苦辛，贱子初不痴。","寡母应给使，灶下无山妻。","野禽当家味，木末无啼鸡。","委身豺虎丛，不死为至怡。","使君西北来，自言归自齐。","了非平生亲，一语云汉低。","前车载以母，后车载以儿。","裂我腰下裤，绣错锦障泥。","毁我箭上镞，刻镂金月题。","凤皇自高翔，谁云藉雉媒。","富贵具本根，偶为君所施。","磨刀不伤手，顽铁羞钝材。","酿酒不醉客，曲糵坐味漓。","报君君上天，谢我当不訾。"]},{"t":"上慎郡王二十四韵","f":"五言古诗","c":["日月扶皇极，朝廷建大中。","弼谐资卫叔，谟赞属姬公。","钟鼎光仪肃，圭璋品节隆。","应龙佐云雨，威凤下梧桐。","天秩班群后，懿亲特总戎。","爪牙深寄托，典礼异尊崇。","儒术河间贵，文章子建雄。","断丝三尺剑，破的九年弓。","坛坫争推毂，诗书妙发矇。","古怀端沕穆，盅器复谦冲。","乐善嬉游简，怜才汲引工。","布衣珠馆集，上客锦筵同。","枚叟专能事，申公辟下风。","雪霏毛颖湿，花落研池红。","湫隘衡门底，尘沙贱子蒙。","枯杨负膏泽，疲马策西东。","卤碛留屯戍，宣房受土功。","翾蠕无振作，天地有帡幪。","白发衰情入，青袍壮志空。","一经韦业废，旷野阮涂穷。","细物迥偏照，虚声误大聪。","谬承脩绠汲，拟使滞流通。","蔼蔼先春草，栖栖伏渚鸿。","抚心增感激，没齿荷昭融。"]},{"t":"上宗侯德少司马二十四韵","f":"五言古诗","c":["彊干敦磐石，和钧藉重臣。","辟疆才实茂，长乐属原亲。","舟楫符康济，衣冠绝等伦。","五兵循职旧，三俊吁贤新。","宠渥期无忝，刚方切自振。","鼎虚金郑重，璧古玉璘霦。","公望推当世，儒宗系此身。","曹臧持节苦，董相下帷频。","理蕴开天地，几先合鬼神。","焦京传竟駮，施孟学宁醇。","道洽文章著，中诚外物驯。","众流稀壅遏，随事及陶甄。","鄠杜栖迟士，龙蛇四十春。","孤心孚泽雉，老骨挺江筠。","麋鹿从归隐，儿童伴食贫。","在閒常勿勿，匪醉日泯泯。","疾有诗书癖，生同草木屯。","潜麟端好缉，屈蠖敢求伸。","摭拾娱枪父，提携辱伟人。","未尝谋面貌，直欲拔风尘。","谬宝帏中秘，回怜席上珍。","骨非千里马，心见九方甄。","紫塞开霜路，青天仰日轮。","大君施解作，万汇入弥纶。"]},{"t":"题易公仙祝融观旭图","f":"七言古诗","c":["赤龙朱鸟纷经营，缔结火德凝阳精。","衡山崱屴耸天半，北斗低亚南斗平。","天风萧萧云冥冥，雨气洗濯芙蓉青。","巴陵之水连洞庭，浸淫岳麓归无形。","中有祝融峰特起，下视苍茫九万里。","夜半日出扶桑东，金芒射天红射水。","光怪翕赫万象分，呼吸帝座通三神。","灵旗侧下湘夫人，寒飙远举云中君。","此时繄谁坐空碧，易君自是湘南客。","眼光炯炯相激射，帝将假君双羽翼，看君高飞横四极。"]},{"t":"铭源侄孙遗玉泉水","f":"五言古诗","c":["有客叩我门，遗我清冷泉。","芳香虽媚人，澹泊开其先。","盐梅杂醯醢，遂分咸与酸。","桂酒和椒浆，自生甘与辛。","人生集百忧，大化禀自然。","何如咀至味，与子保岁年。"]},{"t":"寓城西精舍赠洞文上人","f":"五言律诗","c":["比邻七十载，为客谢淹留。","忍草自长碧，妙香时一浮。","世情争梦幻，佛面老春秋。","愁绝斜阳外，谁家百尺楼。"]},{"t":"赠湘南易淑南 其一","f":"七言绝句","c":["楚塞秋深落日低，蘼芜烟冷鹧鸪啼。","相思南北无消息，魂断当年岘首西。"]},{"t":"赠湘南易淑南 其二","f":"七言绝句","c":["怀香何处问芳荪，文藻风流宋玉存。","万里惊波漂断梗，不堪摇落赋招魂。"]},{"t":"赠湘南易淑南 其三","f":"七言绝句","c":["秋色苍然下洞庭，枫林渔火动青冥。","客窗一弄珊瑚管，似有清猿纸上听。"]},{"t":"观象台二十四韵","f":"五言古诗","c":["肇迹颛蒙辟，昭文象纬悬。","健行标干运，灵曜示蝉联。","覆冒纲维集，盈虚气朔宣。","处高疑倚盖，居默等沦渊。","宿昔神明洽，仪型睿哲传。","造机符动静，剖器敌方圆。","落下功初述，鲜于冶自专。","错银星度密，注水地轮便。","圣智通幽眇，天工绝后先。","双枢交合契，都柱直任权。","梁袅觚棱厉，跗平缔构坚。","石渠深轹辇，铜幂径张弦。","管隶横萧侧，弧分纪限边。","渺茫窥日驭，毫发析星躔。","岁月颁千祀，乾坤蕞一筵。","世难求髣髴，谁足语蹄筌。","矗立青冥表，凭淩沆瀣鲜。","山龙回局曲，云海极雕镌。","六合环尝缀，三辰轨旧沿。","华林遗制薄，文德巧思偏。","瞻眺成真遇，低佪得暂延。","王蕃徒酌古，虞喜谬安天。","弱莛喑宏响，秋蜩惑大年。","傥容恣寝伏，或拟著新编。"]},{"t":"渎山大玉海歌","f":"七言古诗","c":["于阗太璞濡深青，龙膏麟髓凝苍精。","白虹界天月死魄，古斑黝泽同晶瑩。","乾坤灵宝尚舆致，九牛汗喘来燕京。","玉人磨砻靡岁月，仰盂呀口如天成。","刳剔动肉不动骨，元气灏瀚栖百灵。","神龙攫电野马走，鳞甲张满飞石鲮。","海波浴日日转匿，伏阴糅作云霞蒸。","淩兢魑魅辟不若，规模禹鼎援图经。","轮广丈五深二尺，注酒不啻如淄渑。","琼华岛中广寒殿，高寒六月留清冰。","神物纳入诸品却，五山珍榻差抗衡。","此时元氏主中夏，薛禅雅量吞沧溟。","东南片水实视此，沼吴会见游鱼烹。","时移世换玉云改，涂泥汨没归沈冥。","风飙回首岁五百，覆以屋瓦谁经营。","迦陵仙音若相吊，佛灯鬼火同荧荧。","我闻玩物有深戒，玉杯漆器非仪型。","天球不渝石鼓卧，辟雍东序长崇谹。"]},{"t":"送别周西穆南归武林四截句 其一","f":"七言绝句","c":["踏歌争唱白铜鞮，衰柳寒乌落日低。","古瑟无人听悲怨，雪深疲马度青齐。"]},{"t":"送别周西穆南归武林四截句 其二","f":"七言绝句","c":["晓角寒钟入梦奇，蓬莱殿上语移时。","不须更衍春秋传，蔓草秋深董相祠。"]},{"t":"送别周西穆南归武林四截句 其三","f":"七言绝句","c":["板拍清词下浊醅，昔年怀抱得君开。","曾看雷雨秋灯碧，似有荆高侠魄来。"]},{"t":"送别周西穆南归武林四截句 其四","f":"七言绝句","c":["纬萧织薄旧封侯，不信诗书竟白头。","此去春江认归雁，年年飞过古幽州。"]},{"t":"随园雅集图歌","f":"七言古诗","c":["天帝灵宝无端倪，气有精者谁张施。","矞云景星光曜滋，萃为帝子仍金枝。","三驺退食尝委蛇，云旓翠蕤祛绣旗。","道腴内充神外弥，被服儒素循中逵。","西园十亩邸第西，嘉随之义因名随。","药栏鹤栅丁香篱，势有曲折劳攀跻。","神鞭丈石飞峨眉，千年紫柏丛斑皮。","吟亭花馆靡雕几，石床木几閒撑支。","购书不恤千金靡，河閒万卷咸签题。","好古杂以古鼎彝，珊瑚瑟瑟如涂泥。","颓云黯澹陡欲低，大王墨沈时淋漓。","一笔一墨皆天机，草木中有神明栖。","宛转飒沓风雨回，擘窠作字龙■蚭。","园中佳客谁趋陪，曳裾趿履联邹枚。","易居卓踔三湘湄，父子兄弟齐音徽。","烂斑尺二横介圭，大庭作贡孚有时。","落落唐子楚璞劘，学穷焦费非时蹊。","祖丈萧曹家世齐，毓东弱籍通金闺。","依光日月丰沛陲，钦明兰谷骈玉芝。","远情凝注秋水涯，曹江性与糟丘宜。","酒酣往往摹徐熙，吴中澹泉何提提。","星源海鹤方清羸，促膝茗饮传缥瓷。","琤瑽谁叩青颇黎，天风披拂冰蚕丝。","白门上人情我移，锴也拥肿多狂痴。","敝帷故席蒙不遗，蜩螗细响吟清辞。","虎头妙技今丁仪，镕铸万象从范围。","神采栩栩毫端飞，抡工选胜更入微。","补以树石唐画师，锴闻吐握称周姬。","大雅所在群贤归，西园澹荡无他奇，梁园邺都非所几。"]},{"t":"冬夜留宿虚壑精舍暨朱抱光陈行一讲易图夜分抱光援琴弹碧天秋思雉朝飞诸曲行一起复为我剑舞二十四变烛见跋寒月瑩然而霜鸡已再唱矣","f":"七言古诗","c":["少年好奇老好古，陡见神奇在臭腐。","龟龙振跃自然事，妙义乾坤由逆数。","京兆二君同■户，我来夜就双林语。","虚襟远遇神近交，折角曾谁意连拄。","灯昏夜久人坐忘，陈编未掩清琴张。","流虚入变两不测，天风云海声琅琅。","此时万籁肃不闻，一缕一丝呼吸分。","寒飙细坼湘水纹，恍惚欲下云中君。","琴歌既终客起立，子公曾孙剑舞及。","腾踏步武飘风急，回旋五五复十十。","崖倒枯株虎气吹，山划惊雷龙火匝。","一片霜棱不见霜，寒月堕地清冰湿。","始知役神不役气，能使观者皆震詟。","舞罢孱然若处子，此夕何夕叹观止。","机含动静良有以，太虚溶溶曙光启。"]},{"t":"晓月秋河研歌","f":"古风","c":["桐崖尝云有研癖，端溪老坑目所击。","冥搜隐索七百年，宋氏以还岁刳剔。","澒洞或讶海穴穿，嵻崀真疑坤轴坼。","粤中曾见鸠役夫，翻车数十兼渴乌。","洪涛逆吸骇波走，潜虬伏蟒号乾枯。","阴森窟穴裁得罅，坚椎利凿凌空下。","神物可抉不可期，千金一片宁论价。","此石何年出坑水，白日尘沙埋韨底。","眼中取舍亦有时，爱汝瑩然含妙理。","璘璘霦霦翡翠斑，碧月细晕层波閒。","峥峥嵘嵘老蛟骨，抚之荡之若无物。","德苞贞介品正方，宝华黯澹腾古光。","书生得此骄气张，山鬼不敢嗤空囊。","呜乎石君石君聊字汝，昔者桐崖今化土。","人閒茫茫争璞鼠，倘逢陵阳致辛苦。"]},{"t":"梅花 其一","f":"五言律诗","c":["梅花结春思，春思浮云端。","攀折岂终惜，别离良足叹。","江云了无骨，秋水却增寒。","惆怅乌啼夜，遥遥清梦阑。"]},{"t":"梅花 其二","f":"五言律诗","c":["众木正如梦，一枝方自春。","遂令江水上，真见独醒人。","霜月濯我魄，玉琴凝我神。","对君三十日，日日荡愁新。"]},{"t":"紫骝马送别易十八宝亭归湘南","f":"古风","c":["紫骝马，金盘陀。","湘南节士年最少，玉鞭燕赵轻经过。","雪花如掌北山落，错刀寒拭青莲锷。","南枝早梅如雪飞，留君不住君且归。","春风香草丝满挽，此离别心伫君马蹄返。"]},{"t":"磬山若公寄阳羡茶谢答 其一","f":"七言绝句","c":["石磬春风草色寒，禅衣高挂白云端。","吴山楚水三千里，直作微尘一粒看。"]},{"t":"磬山若公寄阳羡茶谢答 其二","f":"七言绝句","c":["盘曲青林接翠微，流泉每送出坡归。","谁知心眼无边际，细雨江南白雁飞。"]},{"t":"磬山若公寄阳羡茶谢答 其三","f":"七言绝句","c":["阳羡春芽浥露匀，石崖名品寄来新。","如何毕扫前尘影，不忘盘阴采药人。"]},{"t":"喜雨","f":"五言律诗","c":["天意关生理，冥冥细雨移。","碧山今日好，芳草一春迟。","喜色浮群动，田家重此时。","老夫理花绪，沾湿鬓边丝。"]},{"t":"溪上同人煮茗作","f":"五言律诗","c":["煮茶石溪水，忽生松风音。","空香领春早，澹白入瓯深。","竖子岂知味，至人同此心。","茗柯有实理，君向静中寻。"]},{"t":"柳花","f":"五言律诗","c":["微薄不自定，漫空时乱飞。","君看可怜态，还有欲生机。","萦惹如求系，漂摇信所归。","翻嫌石苔藓，点点入春稀。"]},{"t":"莺","f":"五言律诗","c":["春阳动幽谷，二月早闻莺。","甘语能无入，金衣竟得名。","林风知乍转，山雨报初晴。","越鸟真痴绝，軥辀止直鸣。"]},{"t":"夜光木歌","f":"古风","c":["枯株何年碎霹雳，嶙峋骨蜕苍龙脊。","在手漓然毛羽轻，细理蹙波肤浅白。","日沈虞渊爝火息，忽然是物标灵迹。","荧荧焱焱光怪生，洞达通明烛幽仄。","清冰一片悬秋空，返景金波摇水碧。","又如白露泻银河，新月离三闪初魄。","照乘已后黄支珠，烛室谁推大秦璧。","吾闻凡木韫真火，以水迫之或成石。","积精残焰不肯死，夺月骈星生玓瓅。","大壑深潭夜将午，神宝高飞下雷雨，谁其致之白龙母。","于嗟乎握瑜怀瑾士岂无，每抱幽光化为土。"]},{"t":"题山水图","f":"七言古诗","c":["秋黛翻空堕江水，平洲仄坂衔江尾。","廿年旧梦今杳然，一旦苍茫落眼底。","江村数家人迹稀，返照何处孤僧归。","清猿白鸟寂视听，但见云水生空晖。","凉风萧萧山欲暮，欲落不落江头树。","鸣榔乍息入浦舟，略彴潜通向山路。","长安八月好雨晴，对之浩然生远情。","伊谁妙手称绝代，能使虚堂接洞庭。"]},{"t":"八月廿四日至山庄草堂荒秽手自芟薙悠然有作","f":"五言律诗","c":["老去诸骸痛，归来两眼新。","堑堙生野兴，劳苦效村民。","甃石馀花落，通篱宿蔓陈。","卢龙五百里，肯作姓田人。"]},{"t":"易公仙公申兄弟，暨王兰谷宿盘山天城寺三日，历盘西剑台诸胜而归，未及追陪怅然于怀赋此却寄 其一","f":"五言律诗","c":["烟草渺无际，卢龙秋色来。","昔人谁舞剑，有客此登台。","楚塞思千里，边风酒一杯。","悲嘶馀老马，落日自低回。"]},{"t":"易公仙公申兄弟，暨王兰谷宿盘山天城寺三日，历盘西剑台诸胜而归，未及追陪怅然于怀赋此却寄 其二","f":"五言律诗","c":["谡谡云际松，亭亭天半峰。","共携紫竹杖，踏碎青芙蓉。","高趣渺难测，野人嗟莫从。","溪南双白鹿，应与数君逢。"]},{"t":"易公仙公申兄弟，暨王兰谷宿盘山天城寺三日，历盘西剑台诸胜而归，未及追陪怅然于怀赋此却寄 其三","f":"五言律诗","c":["入览遂复尽，胜游宁足多。","好山留一半，此意欲如何。","紫盖冥烟雨，天门障薜萝。","上方今不到，珍重待重过。"]},{"t":"月夜有怀","f":"五言古诗","c":["月落秋山昏，时夜凭荒鸡。","星河烂如银，阴虫方苦啼。","相思缔中怀，乃在西河西。","美人厄时命，人事不得齐。","塞门度新霜，坐令百草衰。","高树鸣天风，瑟瑟无已时。"]},{"t":"秋山对雨","f":"七言律诗","c":["五旬有二老狂夫，自比高阳旧酒徒。","亲故浪传侯暗拜，乡邻不罪杖先扶。","晚花当眼还开落，细雨乘秋乍有无。","深喜廌峰峰下路，白沙青石未全纡。"]},{"t":"拟古三首 其一 高村","f":"五言古诗","c":["高村数家村，村东有老妪。","白发而蓬垢，新霜被昏雾。","自言良家子，归作刘家妇。","六十还缉麻，五十且织布。","省身少年日，条桑能上树。","年侵筋力薄，遂为儿子恶。","小儿弃种田，奢心趋瓦注。","大儿能作家，累累仓箧富。","前年岁除夜，萧萧风雪暮。","割羊酴美酒，妻孥各团聚。","健妇不放杯，娇儿不舍箸。","老物实耄荒，曾不值一顾。","馀命系微丝，淫淫涕沾污。","忆昔乳儿时，饥肠分雀哺。","新燕不辞巢，方知旧情误。","一妇前致语，劝妪妪且去。","老媪生三儿，今者邻家住。"]},{"t":"拟古三首 其二 望马台","f":"五言古诗","c":["客行还下马，系马望马台。","落日照山店，肃肃秋风来。","解我腰中钱，酤女瓮底醅。","店中有小儿，洗盏还置杯。","脚踵傅黝漆，头上堆乱柴。","骨相初不恶，眉目生灰炱。","客前问儿年，主人频嗟欸。","村南指高楼，云是儿家遗。","爷娘一旦死，哥嫂今不訾。","饭牛且饲猪，不得容此儿。","草丝一何长，其下同根荄。","兄弟虽异身，其出同胞胎。","寄言生儿人，慎毋遗货财。"]},{"t":"拟古三首 其三 独乐河","f":"五言古诗","c":["茫茫独乐河，汉水今不流。","河边沙草色，还系边城秋。","独行嗟为谁，老妇蒙白头。","提篮拾草子，聊用充乾糇。","野雁生有匹，群鸟各以俦。","嗟为良人弃，弃水今不收。","长城何高高，阴火明戍楼。","宁为戍儿妇，或有梦魂投。"]},{"t":"秋村","f":"七言律诗","c":["万壑衔霜雪濑西，晚芜红树自高低。","秋村近塞寒先落，土著为乡俗不齐。","汉籍已传黄蓓草，燕山今贵锦棠梨。","寂寥服古真痴绝，随事关心亦漫稽。"]},{"t":"送别易公仙南赴浙江署即次留别原韵 其一","f":"七言律诗","c":["南金品节富名流，独许璁珩少匹俦。","魏阙徵求来束帛，越江烟水倦双眸。","牛刀在握羞轻割，犗饵如山肯易投。","善画田生信殊绝，布帆仍挂海西头。"]},{"t":"送别易公仙南赴浙江署即次留别原韵 其二","f":"七言律诗","c":["云尽寥天不见人，楚山楚水负佳晨。","初疑无定方名相，谁信邻虚尚有尘。","渚雁岭猿魂久断，枫香渔火思空陈。","白头陡遇南音客，感激能无意气真。"]},{"t":"送别易公仙南赴浙江署即次留别原韵 其三","f":"七言律诗","c":["几年拾栗从狙公，习隐徐无事迹同。","徒枉鹤书能促驾，须知橘树不分丛。","野情芳草迷汧曲，别思春江注越中。","此去他时各努力，夕阳前路慎飞蓬。"]},{"t":"夜宿蓟门","f":"七言律诗","c":["蓟门古道接乌丸，兵气萧森切骨寒。","函谷实防秦障急，方城却蔽楚天宽。","鸳鸯万骑雄关阵，山海孤军大将坛。","楼橹及今霜月静，幕乌啼罢夜漫漫。"]},{"t":"石将军歌","f":"古风","c":["山阴阴，云冥冥，薜荔苔藓被秋青。","丈石特起猛捷呈，左若按剑右若援弓而抨。","秋风凄雨每夜战，但见骷髅败叶沙上相支撑。","魄为陈汤魂李陵，千秋庙祀为鬼灵。","匈奴过者下马拜，屏息股栗惊威棱。","望夫山，前有闻，石门今复传将军。","丈夫碌碌会终朽，剑倚荒台望暮云。"]},{"t":"兰阳秋望","f":"七言律诗","c":["山色边秋晚翠凝，马兰天险势飞腾。","久湮戍火联三镇，近籍名豪实五陵。","都尉何人传射虎，将军今日竞调鹰。","时平牧马嘶风立，遮莫长河八月冰。"]},{"t":"凤台山蟠松歌","f":"古风","c":["北山有若黄河水，直界中原九万里。","碣石迤北东海西，骧首天门应箕尾。","凤台山高隈隩张，百灵呵护严閟藏。","轩辕尧舜各已葬，开朗今乃归先皇。","卧龙之先先有符，地示灵效松一株。","华盖将从紫极道，翠葆有待金根车。","元精遒气不外荡，诘曲纠盘互低仰。","一折再折怒势伸，忽走圆梢垂八丈。","参差夜吹帝子声，宝瑟秋作湘灵响。","神鸾威凤诡结形，夭矫古貌团深青。","萧骚众木不敢对，彼五大夫何足名。","挺生神物意有在，用蔽风雨如殽陵。","于嗟乎蟠松蟠松汝何异，托根地上今天际。","雪霜万里日月清，郁葱见汝缠佳气。"]},{"t":"上淳郡王","f":"五言古诗","c":["奕叶承天冑，分茅表圣孙。","三辰依帝座，一柱在龙门。","爱育深宫切，谐明近属尊。","丝纶昭宠锡，带砺重屏藩。","谦谢金枝贵，纯涵玉貌温。","尚文崇藻缋，服礼见渊源。","奏雅朱弦直，挥毫翠凤鶱。","古情尝独往，深度复谁论。","寂听蒐忠益，虚襟猎外援。","忽传名士札，报可小人言。","伏处真无赖，多时阙见存。","细鳞私缉缉，薄翼数翻翻。","云水能忘物，樵苏自有村。","空山靡日月，朽木立乾坤。","不信衰迟久，猥叨采撷烦。","涸鱼悲寄辙，羸马辱辞辕。","雉贽从禽父，牛衣谒楚元。","未渝安道节，实感子方恩。"]},{"t":"留宿王兰谷斋中因赠 其一","f":"五言律诗","c":["折节求深造，如君世所难。","儒衣勤正学，禄养喜微官。","虫语空床在，秋灯四壁寒。","能令云卧客，骑马下田盘。"]},{"t":"留宿王兰谷斋中因赠 其二","f":"五言律诗","c":["尊酒寻常事，论心贵以真。","平生敦气节，之子敌交亲。","草木悲秋色，文章质古人。","相逢留信宿，端足慰沈沦。"]},{"t":"将自田盘归与藏公坐倒影潭话声闻事久之乃别","f":"五言律诗","c":["流水自生听，谁知理入微。","藏公真静者，于此发清机。","心耳无边际，声闻有是非。","语馀分手去，潭底白云飞。"]},{"t":"答保雨村户曹秋夜见怀","f":"七言律诗","c":["枯藤日日倚空林，金玉天涯绝信音。","水部多情佳句及，子山无恙小园深。","自招明月三秋色，不动浮云万里心。","回首多君能吏隐，竹斋灯火亦微吟。"]},{"t":"至日","f":"七言律诗","c":["日逢南至日将长，凝冱寒阴转闭藏。","冉冉岁华频托始，冥冥天意重扶阳。","潜蛟午夜吟江海，老木空山立雪霜。","百五日过愁梦醒，东君须借好春偿。"]},{"t":"紫琼岩引","f":"七言古诗","c":["秋风萧萧柳叶黄，邯郸旧梦今苍茫。","一鞭落日者何子，衣衔云水来潇湘。","茅店无声霜月起，又入千秋残梦底。","仙人示以紫琼岩，五色能令双目眯。","吞爻吐凤神往事，中心丹碧镌三字。","长安索米凡几春，逢人不敢宣灵秘。","楚馆宾筵引申白，揭剑乘车为上客。","云龙傅翼拔地飞，倏忽真落神仙宅。","晶帘十二裁清冰，银虬漏戛琉璃屏。","琼岩主人俨然在，再拜稽首称宗瀛。","幻情真境忽交会，梦垒直击邯郸碎。","相逢天外笑无言，蒙头枕藉乾坤睡。"]},{"t":"过传经院赠介上人","f":"七言古诗","c":["纡回路僻城东南，拄杖击户来精蓝。","上人接物寂如水，一切万象能虚含。","几载游心嗜前古，一枝弱管工榰柱。","簪花妍寄卫夫人，崩云妙构钟东武。","或祖仓颉禘史皇，北面程邈臣中郎。","磨砻钟鼎萃光怪，肸蚃篆■丛膻芗。","馀情远趣别有托，石耕铁耨尤难作。","留刀舞刀法各呈，义假筑氏初为削。","我亦萧然多古思，竹书力辨虫文奇。","漏痕在屋不解道，钗脚终应属我师。"]},{"t":"随园雪夜歌","f":"七言古诗","c":["穷阴薄战乾坤交，玉龙十二腾踏骄。","银河水冻不作雨，郁为响雪寒飘潇。","鸟毳梢繁重剖析，蝉翼至薄犹锼雕。","大白内瑩不受污，栗气外迫时相胶。","此时梁园一纯素，繁缛荡涤空明朝。","邹阳鸣玉枚叟相，歌吟不恤清夜遥。","雅音应节骋一击，哀弦入破求深挑。","人籁未息天籁和，铮鏦飒沓轻冰敲。","四更寒月破云出，竹柏低亚晶帘梢。","道心役物且物物，洞澈万有归清超。"]},{"t":"题易啸溪画竹歌","f":"楚辞体","c":["歘吸长风落苍莽，空堂彷佛攒清响。","水烟沙雨白日低，脩竹翛翛出虚敞。","或为筼筜或筱簜，短者盈尺长及丈。","破雪横开劲节圆，飞烟乱叠晴梢仰。","褷参错众态陈，陡揭高标且孤往。","鸳鸯翡翠齐欲栖，紫霄直搏青鸾上。","有时走笔复走意，一片萧森寄无象。","化工在手不在天，尺尺寸寸琅玕长。","谁工此艺称最神，潇湘易君世无两。","潇湘岸头江水波，秋来丛竹多婆娑。","荆扬之贡今若何，东南竹箭非不多。","感君画竹为君歌，竹兮竹兮慎毋老朽枯折空江沱。"]},{"t":"岁除夜有怀铭源","f":"五言古诗","c":["清河何洋洋，水清不受鱼。","北客老不仕，乃向清河居。","我有一端锦，裁衣阙襟裾。","我有三尺剑，斩马马不殊。","于嗟伤心人，委弃当路隅。","众星寒苍苍，今夕逼岁除。","相思漠然来，北风吹户枢。","忧心托远梦，梦远空踟蹰。"]},{"t":"读先太傅宁远伯传敬赋长律十四韵","f":"五言古诗","c":["有汉推猿臂，前朝重虎臣。","茧丝宁作障，执秩足其民。","半壁凭榰柱，群陬失抚循。","蛮氛裁左戢，羌事复西论。","雷火先声疾，乾坤血战频。","竞传边立靖，敢信策称神。","维嬖疑诛赏，论功屡屈伸。","直将成贝锦，谁肯恤劳薪。","献纳更三相，权衡赖一人。","廉颇容善饭，新息偶全身。","异代山河改，王家典籍新。","语方崇起剪，名竟躐甘陈。","小子诚无赖，穷年不自振。","匣中遗故剑，每夜泣风尘。"]},{"t":"过长安古寺次波村韵","f":"五言律诗","c":["琉璃开净域，孤磬窅然清。","不染虚空色，君听起灭声。","妙明无二法，彼佛即群生。","谁證风尘底，逍遥出世情。"]},{"t":"盘山西涧晤王兰谷因寄续云升","f":"七言律诗","c":["晤对王郎西涧边，说君高度迈前贤。","展禽自以和光贵，季札今经博物传。","白首望乡尝独立，青春当酒亦争先。","盐车有马空皮骨，谁恤风尘五十年。"]},{"t":"乙卯九月九日来游西涧西涧主委客去竟赴千像寺斋遂得孤游竟日戊午夏又至西涧涧主又赴千像寺斋时节顿易而踪迹略同追和前作再赋此诗","f":"五言律诗","c":["又委松云去，松云万壑新。","偶然为我有，足以见师真。","落叶證前事，禅心泯客尘。","蘧庐视天地，自属两忘人。"]},{"t":"寄若和尚","f":"七言律诗","c":["今年东涧见国一，临风对坐蒲团石。","松花柳花冥漠飞，白日空山受虚寂。","晴光荧荧楚天末，大江之南大江北。","愁云一片如乱丝，中有相思不堪织。"]},{"t":"黄即生得小铜印其文曰李古物也戊午夏黄集我诗题我集且标印其上而解赠之以李归李符其氏也","f":"古风","c":["轩辕之李曰后土，六相因方各为辅。","古人氏土或氏官，祖姓已先伯阳父。","繄谁范金华我氏，篆势浑噩神媚妩。","之江黄生颇嗜古，此印斓斑垂带组。","授诗未已忽解赠，交深钜鹿无疑沮。","有如故物一旦逢，我我周旋忘尔汝。","噫吁嘻乾坤莽荡事交午，前谁为之后谁主。","达人直作乌号观，得失何须辨荆楚。"]},{"t":"秋风八章留别 其一","f":"七言绝句","c":["秋风奄落凤台山，九月边霜度进关。","一片云旗临驿路，邹阳新载后车还。"]},{"t":"秋风八章留别 其二","f":"七言绝句","c":["软莎高柳护金堤，路拥双桥绝马蹄。","翡翠隔云森碧瓦，天开邸第御河西。"]},{"t":"秋风八章留别 其三","f":"七言绝句","c":["价人特达侍亲藩，天子今尤重弟昆。","龙涧猿岩初不远，禁门旁即大梁园。"]},{"t":"秋风八章留别 其四","f":"七言绝句","c":["九章特赐衮龙衣，藻火山河象服宜。","日暮南宫犹纺绩，敬姜曾设旧风仪。"]},{"t":"秋风八章留别 其五","f":"七言绝句","c":["黄柑飞舸出江干，碧映玻璃七宝盘。","中使雪中颁御赐，一时分饱玉浆寒。"]},{"t":"秋风八章留别 其六","f":"七言绝句","c":["九华灯影簇红罗，丝管年年足燕歌。","午夜一传天上曲，春风春月两相和。"]},{"t":"秋风八章留别 其七","f":"七言绝句","c":["竹简虫文绣作堆，壁书争献冢书开。","久知礼乐河间备，不数相如作赋才。"]},{"t":"秋风八章留别 其八","f":"七言绝句","c":["养疴垂老畏纷纭，初服无心习隐君。","自是深情喜高尚，囊琴容下剡溪云。"]},{"t":"留别诸同人 其一","f":"五言律诗","c":["又复故山去，离离芳草心。","谁能救迟莫，天欲遂飞沈。","世事看云变，交情到子深。","天池雷雨动，珍重伏龙吟。"]},{"t":"留别诸同人 其二","f":"五言律诗","c":["出匣寒吹面，秋冰瑩宝刀。","万金求不得，十载足深韬。","神气平生在，风尘世故遭。","谁为吕虔赠，挥手思徒劳。"]},{"t":"留别诸同人 其三","f":"五言律诗","c":["海内论才杰，多君品骨奇。","每将国士泪，尚与古人期。","物有不可夺，我思时见之。","关门分手去，白日照须眉。"]},{"t":"喜祝豫堂来自吴中因以留别 其一","f":"七言绝句","c":["去年挂席归东吴，今年揽辔来京都。","汉廷待下天人策，一卷遗经辟万夫。"]},{"t":"喜祝豫堂来自吴中因以留别 其二","f":"七言绝句","c":["河外家山叠万层，归休蹑屩复担簦。","监门真负平生德，终竟无言报信陵。"]},{"t":"韨屋灾裁其馀材用搆小亭颜曰瘢柱戏作","f":"五言律诗","c":["八尺方亭子，成之灰烬馀。","得全沟断在，幸免爨桐如。","野色时时入，秋空面面虚。","世谁收弃物，乃作逸人居。"]},{"t":"三器歌 其一 粤鼓","f":"楚辞体","c":["群蛮蠢蠢天不遗，跂行喙息南交垂。","动物有生即有受，蜂虿顺性皆良知。","古之王者大无外，有汉始拓西南夷。","夷德反覆服叛数，用牛马视唯羁縻。","五溪毒淫骆越悍，新息虎节尝行师。","雷霆震惊百蛮詟，爰得铜鼓声天威。","范之为马马龙立，馀鼓千载犹灵奇。","继其事者丞相亮，德音荡涤宣泸微。","荒陬穷徼靡不振夔，三千里安足多王诛剪物不尽物，二轨实与天同规。","迄今蛮种遂滋育，远物若鼓时凭之。","深腔洞底面纸薄，四兽蹲伏如盘螭。","海鱼天马重隐起，宝网细界金蚕丝。","斑淹丹碧古色湛，玄冰凝结灵鼍皮。","吾闻土蚀金则哑，试一弹指轰惊雷。","夫谁呵护乃至此，无乃魍魉无支祁。","呜呼鼓兮鼓兮汝在兹，摩挲我则有所思。"]},{"t":"三器歌 其二 书言府弩","f":"楚辞体","c":["横弓著臂肇为弩，用威天下章大武。","狼弧炯炯俯垂象，弦剡之义睽兼取。","参均九和法久备，岂曰琴氏传自楚。","双牙函郭机絭捷，蹶张未半势已怒。","黄閒白的争树绩，韩推蹊子推巨黍。","弩师授法不授器，此物沈沦半泥土。","精芒一朝韨底出，绿沈照眼谁能估。","呜呼弩兮弩兮慎自处，不须再入书言府，世有陈音当事汝。"]},{"t":"三器歌 其三 十二辰鉴","f":"古风","c":["明者治物先治内，易戒曾闻日中沫。","轩辕铸镜盖有故，宁仅山林辟魑魅。","此镜何年始成器，背环十二虫文字。","冠笏鹄立象安取，青马夹纽知何谓。","大白由来不受污，白旃玄锡都无赖。","出箧冷然金井深，碧月明水秋阴会。","对之一再神气肃，毫发不敢中藏秽。","呜呼宝镜照人人尽爱，所贵君子通其类。"]},{"t":"感化寺多古松有轩三楹时入灵籁远臻法师以听涛名之且制以图为赋长局","f":"古风","c":["东竺上人寻绘素，盘山全体久毕露。","骥毛龙甲少为贵，远师别搆图中趣。","圆机离相转即相，能使作者神明注。","焦墨虚拓岩下云，秃颖枯扫沙头树。","莲花池东乱石西，隐开一尺盘阳路。","听涛轩，凿空起，乡者在山今在纸。","闻师善说法，能论一切无，与彼一切有。","即此请师申妙理，毕竟云何托根柢。"]},{"t":"秋山对雨有怀陈氏兄弟赋诗三韵而陈书适至遂成一律却寄","f":"五言律诗","c":["风吹岫云合，细雨一丝丝。","天欲深秋色，怀人属此时。","大江流竟下，芳草怨凄其。","适报三千里，投书慰别离。"]},{"t":"天城寺定光塔下作","f":"七言古诗","c":["龙神何年奉舍利，秘师血写莲花字。","山河大地清净中，忽然石塔淩高空。","风吹塔铃若太息，黄叶自下秋林夕。"]},{"t":"题天城寺慎淳二王泐石书","f":"五言古诗","c":["岣嵝山前石，琅琊台上辞。","漫张它日事，徒启后人疑。","有蓟承东甸，维盘镇左陲。","久徼先帝赏，今结二王知。","日月标文藻，虫鱼继鼎彝。","天龙看独举，丹凤复双仪。","气浑全神入，痕深捷势移。","直教金并镂，不惜玉同劙。","秋藓毋侵蚀，高云或蔽亏。","涧增飞白胜，峰扼翠屏危。","子固宁轻命，中郎剧好奇。","定知千载下，争拓寺西碑。"]},{"t":"藏公生塔落成喜赋","f":"五言律诗","c":["岂必造生塔，为公终此心。","后来传好事，君子或知音。","古道久不作，交情多面深。","沃洲山下路，曾见几人寻。"]},{"t":"分花漫赋","f":"七言律诗","c":["吾衰强了生前事，兴至还分雨后花。","却引茑萝阑虎落，莫因鸡犬恼邻家。","小园曲径随方改，远水分流入圃斜。","青帝有情应念我，十年春色早须赊。"]},{"t":"芳草","f":"五言律诗","c":["芳草正萋碧，肃然丽清霜。","王孙杳不见，蝴蝶飞以黄。","紫塞下寒吹，浮云微夕阳。","残荷张晚盖，七十二鸳鸯。"]},{"t":"村父采菊见遗","f":"七言律诗","c":["菊花不见已三年，惨澹秋风落木前。","采撷是谁能及此，依栖缘汝一愀然。","照来白发羞相并，嗅入衰心绝可怜。","江芷泽兰今在否，怀香珍重欲霜天。"]},{"t":"九日石堂峪力疾登高适王兰谷遣使遗鲑菜江洲白衣遂复同之喜而有作","f":"七言律诗","c":["衰病经时成委顿，石堂九日强登临。","青山老变穷秋色，霜树寒深不贰心。","已忍平居常索莫，每逢佳节转沈吟。","长安满目亲知在，书札兰阳辱好音。"]},{"t":"秋花行因花佣顾五作","f":"古风","c":["盘山绝远南西门，秋花强致佣真惛。","历历鹿鹿随车轮，十日离土伤本根。","长条缚急乾叶渴，水华土膏徒具存。","于嗟色态半憔悴，三嗅聊复投幽芬。","贤豪失路气沮丧，对此亦足伤心魂。","由来万物任遭遇，集有枯莞谁能论。","盘山上人争好善，恼花萎落怜佣贫。","敛钱买花不计直，花佣高唱归花村。","颒水祝花花不活，佣售弃物真称神。","君不见牛商楮贾利各在，阳翟大贾且贩秦，笑洴澼统徒终身。"]},{"t":"九月十有四日孤游花下悠然成咏效陶体","f":"五言古诗","c":["风静川无云，天地呈清秋。","清秋此佳日，抱景成孤游。","林亭鸟雀喧，物类各有求。","得失遗外役，耳目易以酬。","晚花散疏香，遂为静者收。","山空白日下，此意常悠悠。"]},{"t":"晚菘行赠石堂慎上人","f":"七言古诗","c":["石堂上人能种菘，种菘不与寻常同。","丰根大叶厚其里，凌跞百蔌维君宗。","坟卢助骨云助气，乳泉饱沃真香秾。","肤凝秋雪薄寒入，心敛石蜜微甘充。","齿牙迎击了无物，厥滓作梗犹凡庸。","迩来武遂产此种，十本入韨千钱空。","乃知树艺贵以性，斯土协洽还丰茸。","空山野老病脾泻，不谓得此供朝饔。","倾盘下箸不惜尽，屠门大嚼乌足雄。","养终吾老终藉汝，上人慎勿疑周颙。"]},{"t":"收稼了咏怀","f":"五言律诗","c":["农事各已了，田家深闭门。","北风吹老树，黄叶下秋村。","一径往来绝，空场鸟雀喧。","先天徒已凿，且得后天存。"]},{"t":"望大龙潭","f":"五言律诗","c":["冷翠转深黑，望之如空天。","森沈白日底，傲睨群峰前。","险势开阴峡，飞流注大川。","苍龙不作雨，常得抱珠眠。"]},{"t":"秋雪","f":"五言律诗","c":["白日常年好，空明九月时。","阴阳今欲战，雨雪晚交持。","势合溪云长，寒深木叶危。","清商杂流羽，取瑟一调丝。"]},{"t":"可惜","f":"五言律诗","c":["徒有千秋意，无由质古人。","此生良可惜，他日得谁论。","乾鼠藏多秘，飞龙好必真。","等身书卷在，糟粕厌空陈。"]},{"t":"所思","f":"五言律诗","c":["日夕有所思，所思端属谁。","关河愁绝处，天地酒醒时。","木叶夜来下，秋风江上吹。","倚楼寻苦调，一一入参差。"]},{"t":"不见","f":"五言律诗","c":["不见西邻好，当时及老成。","浮云随雨散，春草入秋生。","旧俗悲前事，新愁惑旅情。","哑哑乌鹊语，犹作故林声。"]},{"t":"漫与","f":"五言律诗","c":["老怀徒漫与，世事懒相干。","路阻崔亭伯，天羁管幼安。","升沈嗟烂熟，交接畏多端。","岁晚幽兰曲，虚堂自一弹。"]},{"t":"不信","f":"五言律诗","c":["不信句吴祀，千秋以仲传。","将何酬至德，直欲问皇天。","蛮貊求仁易，神明忌道全。","请看嬴博恨，宿草亦芊眠。"]},{"t":"扫草子","f":"五言古诗","c":["北风晨萧萧，柳箕枲其帚。","父老何所之，宿草栖予亩。","一母百其子，亦足糊予口。","扫之扬其根，终日不盈斗。","道周坐白沙，哀哀啼寡妇。","玄驹羞其穴，田鼠西北走。","众庶实每生，谁能坐相守。","淅米必以水，凿谷必以臼。","父老聊归休，父母在女右。"]},{"t":"题牧山画松","f":"七言古诗","c":["平生爱松多苦节，独立秋风共萧瑟。","真精元气通往来，每与长松化为一。","城东牧山亦有得，能使灵明两相契。","伸纸有时放直笔，阑阑珊珊扫枯蘖。","兴深风雨黯欲低，意走毫芒险成绝。","蟠龙大泽一节申，野鬼穷岩夜阴泄。","遂恐神物不自朽，霹雳当空猛摧裂。","廌翁廌翁万事毕，老骨颓唐直如杌，其与此松并生灭。"]},{"t":"上方望溪宗伯 其一","f":"五言古诗","c":["丈夫弧矢志，少小应征繇。","屯边隶充国，代马惨不骄。","二十走淮徐，畚锸尝自操。","蜃蛤贵时变，椒兰移所遭。","微生苦不化，造物成虚劳。","栖迟坐衰白，惄焉心烦骚。"]},{"t":"上方望溪宗伯 其二","f":"五言古诗","c":["烦骚当告谁，大命愧虚受。","皇天匪不高，后土匪不厚。","菅蒯虽可绳，其如索云朽。","奄忽百岁尽，具体惭父母。","于嗟千载下，焉知某为某。","长为老农夫，荷锄寄南亩。"]},{"t":"上方望溪宗伯 其三","f":"五言古诗","c":["南亩何膴膴，粤彼沧海浔。","孤云黯栖薄，岁晚无终深。","山桑不中矩，硕鼠多野心。","弃物有不遗，辛苦劳见寻。","多闻信臼季，高谅张虚襟。","草木具本性，感激增悲吟。"]},{"t":"赠余星源","f":"古风","c":["万壑蟠胸故支拄，青苍历历纷难数。","十年抑郁不可吐，一旦余生能貌取。","江有湘，山有岷。","青林绿波渺无极，点染万里毫芒分。","渔歌牧唱若有闻，或留虚无成白云。","野人平生怀，一切无所注。","爱山有若麛，爱水有若鹜，手不能写心则悟。","我能对君之画图，内役神明日来去。"]},{"t":"易十六淑南许为我作萝村图诗以识之","f":"古风","c":["淑南许作萝村图，满纸为我扫古翠。","秋林护石溪入云，一尺一寸期有味。","凿空构虚固以变，不妨古拙兼狂肆。","沈冥黯淡妙入神，逼迫山鬼幽阴至。","用通大钧造物理，飞笔走墨臣行意。","我有青藤杖，尝之山之垂。","我有乌角巾，尝临水之湄。","盘阴傥遇息阴者，此卷卢胡笑所为。"]},{"t":"绞丝斲木行赠金子","f":"古风","c":["太古作器琴为先，绞丝斲木师自然。","吴中金子传正传，入指清籁鸣其天。","傥寘清庙明堂前，编钟颂磬应四悬。","融泄民物登万年，不特授技如成连。","圣人之道中和且平。"]},{"t":"江南","f":"五言古诗","c":["江水是弱水，久已沉羽毛。","江水是江水，我岂无轻舠。","中流双鸳鸯，唼波影凌乱。","鸳鸯且莫飞，我有好针线。","绣在合欢被，与汝日相见。"]},{"t":"当来日大难","f":"古风","c":["驾青骊，骖驳牛，西上皋皋兰山，直入昆仑丘。","求西王母不可得，归来还作人间游。","人间逼仄，来日几何。","但见北邙之山，如杨如麻，累累坡冢皆谁何？","昨日前日，对酒当歌。"]},{"t":"新秋雨中塞晓亭侍郎招饮署斋即席分赋","f":"七言律诗","c":["飞鸟无心惜羽翰，游鱼随处狎波澜。","于人岂敢行藏异，好我何妨礼数宽。","头白亲知稀握手，酒深风雨一凭阑。","年光向晚贪高会，已醉辽东管幼安。"]}]};